(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c27"]=[{"id":"00010851","register_sub_id":"101","register_pk":"201686","name":"西村屋本館大広間棟","kana":"にしむらやほんかんおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所469","lat":35.625312,"lng":134.80561,"geo_status":"db","era":"昭和前期／昭和中期・平成3改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積322㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0621","desc":"老舗旅館の入口脇に建つ木造二階建の大広間棟。南の通り側に入母屋の妻を見せ、西面に並べる窓に庇と高欄を廻らせ、落着きある外観を呈する。二階は洋小屋を用いた八〇畳大の大広間で、折上格天井を張り、南面に大振りな座敷飾、北面に舞台を設け豪壮に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010851"},{"id":"00010852","register_sub_id":"101","register_pk":"201687","name":"西村屋本館平田館","kana":"にしむらやほんかんひらたかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所469","lat":35.625857,"lng":134.804578,"geo_status":"db","era":"昭和35／昭和後期改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造2階建、瓦葺、建築面積591㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0622","desc":"客室から庭への目線が交差せぬよう配置計画された客室棟。吹抜けのロビーに橋を架け、天井に四季の花を描き、廊下はガラスブロック壁で採光する。各室は数寄屋を基調とし、伝統意匠と現代技法を巧みに融合させる。細部にも設計者平田雅哉の作風が窺える優品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010852"},{"id":"00010853","register_sub_id":"101","register_pk":"201688","name":"西村屋本館門及び塀","kana":"にしむらやほんかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所469","lat":35.625158,"lng":134.805665,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口3.3m、左右袖塀及び潜り戸付 塀 木造、瓦葺、総延長33m、供待付","structure_material":"門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0623","desc":"敷地南正面に構える門の左右に袖塀を付設し、折曲りに塀を廻らせる。門は大型の薬医門で男梁を舟肘木で受け、屋根に緩く起りをもたせて優雅に見せる。西側には供待を附属する。塀は竪板張で基礎の前面に地元産の玄武岩を並べ、老舗旅館らしい趣ある構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010853"},{"id":"00006169","register_sub_id":"101","register_pk":"107153","name":"西山酒造場店舗兼主屋","kana":"にしやましゅぞうじょうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県丹波市市島町中竹田1171他","lat":35.241241,"lng":135.129135,"geo_status":"db","era":"明治24頃／昭和27頃改造","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積204㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0270","desc":"市道に西面して建つ。建築面積２０４㎡，木造２階建，入母屋造，妻入，桟瓦葺とする。正面１階は真壁造で木製格子を嵌め，２階は軒下に瓦庇及び虫籠格子を付ける。通り土間沿いに和室を並べる。北側に座敷を突出させ，当地で特徴的な座敷中門造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006169"},{"id":"00006174","register_sub_id":"101","register_pk":"107158","name":"西山酒造場塀","kana":"にしやましゅぞうじょうへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県丹波市市島町中竹田1171他","lat":35.24124345,"lng":135.12903794,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、総延長45m、搬入口付","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0272","desc":"店舗兼主屋の両側に延びる。高さ３．３ｍ，延長４５ｍ，木造，桟瓦葺。真壁造で，腰を杉板の縦板張，上部を漆喰塗とする。軒高を店舗兼主屋の１階軒よりも高くした高塀で，酒造業大店の広大な敷地正面を飾る格式あるつくり。町並み景観の形成にも寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006174"},{"id":"00014654","register_sub_id":"101","register_pk":"515196","name":"橋乃家本館","kana":"はしのやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬792","lat":34.79713889,"lng":135.24754444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造3階建、鉄板葺、建築面積162㎡","structure_material":"木造3階建","registered":"2023.08.07(令和5.08.07)","register_no":"28 - 0791","desc":"有馬温泉街の入口でかつての太古橋の袂に所在する木造三階建旅館。入母屋造妻入鉄板葺、二・三階は川沿いを眺める高欄付の入側を巡らす。客室は階段室を中心に配置し、個別に床構えを備える。格天井で舞良戸を構えた広い玄関は温泉街の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014654"},{"id":"00004273","register_sub_id":"101","register_pk":"105263","name":"フットテクノビル","kana":"ふっとてくのびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市中央区元町通5-2-8","lat":34.684254,"lng":135.181808,"geo_status":"db","era":"大正10／昭和24改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積178㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0175","desc":"旧外国人居留地の西に接する地域に建つ事務所ビルで，帝国生命保険神戸出張所として建設。鉄筋コンクリート造４階建で，栄町通に南面し，西南角に円みをつける。１階は腰花崗石張，上部擬石仕上げ，２階以上は改装されているが，創建時の骨格をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004273"},{"id":"00003576","register_sub_id":"101","register_pk":"104566","name":"鳳鳴酒造事務室一","kana":"ほうめいしゅぞうじむしついち","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県篠山市呉服町48","lat":35.07673138,"lng":135.22025214,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積6.3㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0128","desc":"敷地の北側街路に面し，主屋の西側に建つ。木造平屋建，桟瓦葺の小規模な建築で，内部は一室とする。屋根は街路寄りに棟を設け，南に向かってほぼ片流れ状にかける。街路立面の上部は漆喰塗りとし，中央に虫籠窓風のアクセントを設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003576"},{"id":"00003575","register_sub_id":"101","register_pk":"104565","name":"鳳鳴酒造主屋","kana":"ほうめいしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市呉服町46","lat":35.076664,"lng":135.22032748,"geo_status":"db","era":"文化元","year":1804,"year_source":"db","year_min":1804,"year_max":1804,"year_label":null,"structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0127","desc":"篠山城の北東，呉服町に所在する造り酒屋の主屋。北側で街路に面して平入とするつし二階の建物である。入口から通り土間を背面まで通し，東側を床上部とする。街路に面した緩やかなむくりの瓦屋根が特徴的で，城下町篠山の景観を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003575"},{"id":"00010321","register_sub_id":"101","register_pk":"199094","name":"松尾ビル（旧小橋屋呉服店神戸支店）","kana":"まつおびる（きゅうおばしやごふくてんこうべしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市中央区元町通6-5-6他","lat":34.683497,"lng":135.180124,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造5階一部地下1階建、建築面積369㎡","structure_material":"鉄筋コンクリート造5階一部地下1階建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0600","desc":"元町通り東側の角地に西面して建つ百貨店建築。外観は一階正面に三連大アーケード、上階に縦長三連アーチ窓を表し、三段迫出しの窓台など要所に表現派風の曲線を用いる。内部も柱頭飾、梁や廻縁の蛇腹引など、豊かな装飾をもつ。大正期の意匠の傾向をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010321"},{"id":"00010219","register_sub_id":"101","register_pk":"198052","name":"三木屋西館","kana":"みきやにしかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所487","lat":35.62505618,"lng":134.8059964,"geo_status":"db","era":"昭和2／昭和中期・平成25改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"28 － 0598","desc":"東館の西に並び建つ温泉旅館建築。東館より建ちの低い入母屋造桟瓦葺屋根の二階建建物で、東館と接続し、南面にガラス窓をたてて、二階に手摺を設ける。内部は上下階とも客室を配する。東館とともに、大正一四年北但地震後の城崎温泉復興期の姿を良く留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010219"},{"id":"00010218","register_sub_id":"101","register_pk":"198051","name":"三木屋東館","kana":"みきやひがしかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所487","lat":35.625131,"lng":134.80623316,"geo_status":"db","era":"昭和2／昭和中期・昭和47改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造3階建、瓦葺、建築面積348㎡","structure_material":"木造3階建","registered":"2014.10.07(平成26.10.07)","register_no":"28 － 0597","desc":"城崎温泉のほぼ中央に所在する三階建の温泉旅館建築で寄棟造桟瓦葺である。各階とも同じ広さの矩形平面とし、北面に玄関を附属し、南側は庭園に面する。一階はロビーと宴会場、二階は客室、三階は大宴会場とし、舟底天井を見せる。端正な意匠の木造和風旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010218"},{"id":"00007524","register_sub_id":"101","register_pk":"108506","name":"武庫川女子大学甲子園会館（旧甲子園ホテル）","kana":"むこがわじょしだいがくこうしえんかいかん（きゅうこうしえんほてる）","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市戸崎町6他","lat":34.734264,"lng":135.377945,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造4階地下1階建塔屋付、一部瓦葺、建築面積2056㎡","structure_material":"鉄筋コンクリート造4階地下1階建塔屋付","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0385","desc":"敷地中央に建つ。建築面積２,０５６㎡、鉄筋コンクリート造、地上４階地下１階建、緑黄色の桟瓦葺。起伏に富んだ空間構成や、テラコッタタイルによる幾何学意匠などライトの建築手法を基調としつつ、和風意匠を加味してまとめた、関西の本格的ホテルの先駆例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007524"},{"id":"00010682","register_sub_id":"101","register_pk":"201256","name":"ゆとうや旅館詠帰亭","kana":"ゆとうやりょかんえいきてい","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕373","lat":35.625472,"lng":134.809664,"geo_status":"db","era":"昭和3年／昭和8年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積275㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"28－0608","desc":"敷地東方に建つ別棟で、皇室などの宿所としても使われた。平屋建の詠帰亭と二階建の扶老亭を雁行配置とし廊下で繋ぐ。詠帰亭は唐破風、扶老亭は切妻の玄関をそれぞれ付し、内部は上質な座敷を並べ、浴室、洗面所や洗面脱衣室も良材による和風意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010682"},{"id":"00010687","register_sub_id":"101","register_pk":"201261","name":"ゆとうや旅館表門及び塀","kana":"ゆとうやりょかんおもてもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕373","lat":35.625842,"lng":134.809459,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"表門 鉄筋コンクリート造、瓦葺一部銅板葺、間口3.8m 塀 木造、瓦葺一部銅板葺、総延長8.5m","structure_material":"表門 鉄筋コンクリート造","registered":"2015.08.04(平成27.08.04)","register_no":"28－0613","desc":"敷地北に道路に面して建つ。薬医門形式の入母屋造桟瓦葺で軒先を銅板葺とする。太いコンクリート造の本柱と脇柱の表面を、赤錆色の砂利の洗出し仕上げとして玉石を散らして埋込み、その上に立てた細い柱で軒を支える。独創的な意匠を見せる、老舗旅館の表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010687"},{"id":"00010686","register_sub_id":"101","register_pk":"201260","name":"ゆとうや旅館土蔵","kana":"ゆとうやりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕373","lat":35.625112,"lng":134.809111,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積75㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"28－0612","desc":"敷地南西隅に建つ大型の土蔵。桁行五間梁間四間、土蔵造二階建で、屋根を切妻造の桟瓦葺とする。外壁は漆喰塗で腰は北面、西面を海鼠壁、他は石造風のモルタル塗目地切り仕上げとし、軒は塗込めとする。内部は中央に通し柱を建て、小屋は牛梁に登梁をかける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010686"},{"id":"00010683","register_sub_id":"101","register_pk":"201257","name":"ゆとうや旅館渡り廊下","kana":"ゆとうやりょかんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕373","lat":35.625333,"lng":134.809339,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"鉄筋コンクリート造及び木造平屋建、瓦葺及び銅板葺、建築面積168㎡","structure_material":"鉄筋コンクリート造及び木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"28－0609","desc":"敷地南の建物を結ぶ渡り廊下で、途中に浴室、東屋を設ける。鉄筋コンクリートと木造の混構造で、数寄屋意匠を基調とするが、付近の天然記念物玄武洞に因む六角形平面や六角格子壁を取入れ、松、竹、梅を模した飾り窓を配するなど、随所に奇抜な造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010683"},{"id":"00012434","register_sub_id":"101","register_pk":"531758","name":"旅亭文市楼旧館","kana":"りょていぶんいちろうきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県三木市本町三丁目1385-1他","lat":34.79506111,"lng":134.9828,"geo_status":"db","era":"大正13年／昭和前期増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積374㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-691","desc":"旧城下町人地の入組んだ路地奥にある。旧館は入母屋造妻入の大広間棟と客間棟からなり、大広間は書院風の格調高いつくりとし、各客間は数寄屋風や草庵風の意匠を用いて個性豊かにつくる。戦前の地方都市の営みの一端を物語る伝統木造の料理旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012434"},{"id":"00012435","register_sub_id":"101","register_pk":"531759","name":"旅亭文市楼新館","kana":"りょていぶんいちろうしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県三木市本町三丁目1385-1他","lat":34.79521944,"lng":134.9829,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"28-692","desc":"旧館客間棟の背面に渡廊下で接続する。入母屋造の座敷棟で、中廊下をＴ字に通して客間五室を配する。各客間は傘天井や網代天井を使い分け、入口に板葺の庇を付すなど数寄屋好みの意匠を凝らす。旧館とともに戦前に都市部で興隆した料理旅館の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012435"},{"id":"00006235","register_sub_id":"101","register_pk":"107219","name":"小田垣商店店舗","kana":null,"category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市立町19-5","lat":35.072399,"lng":135.223373,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積193㎡","structure_material":"木造平屋一部2階建","registered":"2007.10.02(平成19.10.02)","register_no":"28 － 0283","desc":"篠山城下の東方に所在する商家地区を南北に通る旧京街道に西面して建つ。桁行１５ｍ、梁間１２ｍ規模、切妻造、桟瓦葺、平入の木造つし２階建で、内部は北半を土間とし、外部は軒下等を塗り込め、妻面に水切瓦を付ける。街道景観の中核をなす大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006235"},{"id":"00007790","register_sub_id":"101","register_pk":"108771","name":"小川又兵衛商店内蔵","kana":"おがわまたべえしょうてんうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市鵲町8-1","lat":34.6777209,"lng":135.83229961,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積32㎡","structure_material":"土蔵造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"29-0133","desc":"短冊形の敷地の中央、渡廊下の東側に接続する。桁行５．５ｍ梁間３．８ｍの土蔵造平屋建、切妻造桟瓦葺。南面に下屋庇を付設。西面は、出入口周囲を黒漆喰塗で木瓜型に象り、切目縁を設け渡廊下の縁と繋ぐ。奈良町における町家の屋敷構えを示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007790"},{"id":"00007788","register_sub_id":"101","register_pk":"108769","name":"小川又兵衛商店店舗兼主屋","kana":"おがわまたべえしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市鵲町8-1","lat":34.67772528,"lng":135.83205138,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積144㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"29-0131","desc":"元興寺の東向かいの細長い敷地に建つ。間口８．８ｍの木造２階建、切妻造桟瓦葺。出格子を設ける前方の表屋と後方の主体部、その間を繋ぐゲンカンからなる表屋造。南側に通り土間、表屋にミセノマ、主体部に居室等を配し、奈良町の伝統的な町家の形態をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007788"},{"id":"00007789","register_sub_id":"101","register_pk":"108770","name":"小川又兵衛商店渡廊下","kana":"おがわまたべえしょうてんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市鵲町8-1","lat":34.67771635,"lng":135.83218562,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"29-0132","desc":"店舗兼主屋の東端と内蔵を繋ぐ廊下で、桁行７．８ｍ梁間４．８ｍの木造平屋建、桟瓦葺である。南側を通り土間、北側を物入及び便所とし、北側の中庭に面して高欄付切目縁を設ける。瀟洒な意匠で、町家における内庭の空間構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007789"},{"id":"00002072","register_sub_id":"101","register_pk":"103062","name":"菊水楼旧本館","kana":"きくすいろうきゅうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県奈良市高畑町1130","lat":34.68179072,"lng":135.83448634,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積299㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0030","desc":"敷地は春日大社参道に面した角地にあり，背後に荒池を望む景勝地に建つ。入母屋造，桟瓦葺の純和風木造２階建で，料理旅館として長い歴史をもち，多くの賓客を迎えた。現在も建築当時の姿を保ち，格式ある料理旅館のたたずまいは市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002072"},{"id":"00002073","register_sub_id":"101","register_pk":"103063","name":"菊水楼本館","kana":"きくすいろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県奈良市高畑町1130","lat":34.68177,"lng":135.834259,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造3階建、瓦葺、建築面積293㎡","structure_material":"木造3階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0031","desc":"旧本館に接続して明治３４年に増築。入母屋造，桟瓦葺の純和風木造３階建で，正面に突出する入母屋造の玄関天井に菊水の彫刻，１階壁面には菊花を象った丸窓をあしらう。三条通からの眺望は表門とともに大鳥居前の景観に欠くことの出来ない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002073"},{"id":"00010224","register_sub_id":"101","register_pk":"198057","name":"旧川本家住宅蔵及び納屋","kana":"きゅうかわもとけじゅうたくくらおよびなや","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県大和郡山市洞泉寺町10","lat":34.64639,"lng":135.784556,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積64㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"29 － 0213","desc":"敷地西辺に建つ土蔵造二階建で、座敷棟茶室と渡廊下で接続する。北側を切妻造本瓦葺の蔵、南側を切妻造段違で桟瓦葺の納屋とし、東面に瓦葺の庇を付ける。外壁は漆喰塗で腰を竪板張とし、蔵の戸口枠は木瓜形につくる。敷地の奥に重厚な構えを見せる附属屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010224"},{"id":"00010223","register_sub_id":"101","register_pk":"198056","name":"旧川本家住宅座敷棟","kana":"きゅうかわもとけじゅうたくざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県大和郡山市洞泉寺町10","lat":34.646394,"lng":135.784691,"geo_status":"db","era":"大正13／昭和前期・昭和中期改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積127㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"29 － 0212","desc":"本館の西に坪庭を介して接続する木造二階建で、切妻造桟瓦葺とし、西面北に茶室、南に浴室、便所を張出す。南側は一階が厨房、二階が髪結場など営業用で、北側一階の座敷一二畳や二階の六畳二室は居住用の室である。南面高塀には猪目形の透かし窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010223"},{"id":"00010222","register_sub_id":"101","register_pk":"198055","name":"旧川本家住宅本館","kana":"きゅうかわもとけじゅうたくほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県大和郡山市洞泉寺町10","lat":34.646394,"lng":135.784795,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造3階建、瓦葺、建築面積135㎡","structure_material":"木造3階建","registered":"2014.10.07(平成26.10.07)","register_no":"29 － 0211","desc":"街路に東面する木造三階建の旧妓楼で、切妻造桟瓦葺とする。正面は一階に瓦葺庇をつけ、中央を戸口、両脇を出格子とする。上階も繊細な出格子に小庇を付ける。一階は帳場や仏間で、上階の客室は三畳から八畳で色土壁に釣トコを備える。歓楽街の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010222"},{"id":"00013870","register_sub_id":"101","register_pk":"507828","name":"旧吉野銀行桜井支店","kana":"きゅうよしのぎんこうさくらいしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県桜井市大字桜井951","lat":34.51164722,"lng":135.84775833,"geo_status":"db","era":"昭和5年／平成30年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積100㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"29 － 0324","desc":"桜井駅前の商店街の道路に北面して建つ。木造二階建、寄棟造鉄板葺。外壁は一階は人造石仕上、二階はタイル貼で、竪長窓を並べコーニスを卵鏃風文様とデンティルで飾る。内部東半の客溜は吹抜け上部にギャラリーを廻らす。意匠簡明ながら本格的な木造洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013870"},{"id":"00006602","register_sub_id":"101","register_pk":"107585","name":"旧六十八銀行八木支店","kana":"きゅうろくじゅうはちぎんこうやぎしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町1-501-2","lat":34.508617,"lng":135.792694,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積157㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"29 － 0112","desc":"近鉄橿原線八木西口駅近くに，国道に北面して建つ。両翼を薄く張り出したルネッサンス風の形態をとり，中央部の玄関とその上部の半円形窓の左右にイオニア式の円柱を配する。幾何学的な細部や玄関廻りタイルの芋目地貼等に新味が認められる。設計は舟橋俊一。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006602"},{"id":"00000454","register_sub_id":"101","register_pk":"101444","name":"古梅園事務所","kana":"こばいえんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７他","lat":34.68061565,"lng":135.82752115,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建，瓦葺，建築面積120㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0006","desc":"店舗の南側に接続する平入，つし２階の建物で，立ちは軒庇とも店舗より一段低いが，一体的な意匠にまとめる。北端は出入口で大戸口とし，中央部は事務室で格子戸をはめる。南端部は車庫に改造したが，今も奈良町の伝統的な店構えをよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000454"},{"id":"00000453","register_sub_id":"101","register_pk":"101443","name":"古梅園店舗","kana":"こばいえんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68074433,"lng":135.82751651,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建，瓦葺，建築面積56㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0005","desc":"旧奈良町の一画にある老舗の製墨業古梅園の店舗で，風格ある看板を掲げる。平入，つし２階の伝統的な構えになり，正面は庇及び上屋ともせがい造りとする。格子は多用せず開放的になるが，外壁を黒漆喰塗とした重厚な店舗として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000453"},{"id":"00000459","register_sub_id":"101","register_pk":"101449","name":"古梅園西内蔵","kana":"こばいえんにしうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68078921,"lng":135.82707253,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"土蔵造2階建，瓦葺，建築面積55㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0011","desc":"敷地のほぼ中央北よりに東西方向に建つ大型の土蔵で，南面に桟瓦葺きの下屋を取り付ける。 外観は２階の東面及び南面に小庇付の開口部を設け，漆喰仕上げの軒蛇腹付の外壁や外引きの防火戸が意匠を整える。 内向きの生活空間の西を限る土蔵でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000459"},{"id":"00003687","register_sub_id":"101","register_pk":"104677","name":"ぜいたく豆本舗本店主屋","kana":"ぜいたくまめほんぽほんてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市角振町24-1","lat":34.682068,"lng":135.827423,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"29 － 0070","desc":"奈良市の中心地，三条通に面する町家。道路拡張により前面側は１間ほど切縮められている。当初は１階西側を床上部としたが，数度の改造を経て総土間に改められた。つし２階の外観で，２階には東西２列に居室を配する。奈良町の景観を今日に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003687"},{"id":"00010989","register_sub_id":"101","register_pk":"208959","name":"玉や主屋","kana":"たまやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県葛城市當麻元當麻方1242","lat":34.51564,"lng":135.697334,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"29-0228","desc":"當麻寺門前の角地に建つ二階建のもと旅籠。西面入母屋造、東面切妻造、起りのある桟瓦葺で下屋と高欄を廻らす。外周に格子をたてるほか、壁に「松に鶴」の鏝絵を飾り、また軒の持送りに宝珠を彫刻するなど華やいだ雰囲気をもち、古刹門前の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010989"},{"id":"00010990","register_sub_id":"101","register_pk":"208960","name":"玉や離れ座敷","kana":"たまやはなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県葛城市當麻元當麻方1242","lat":34.515727,"lng":135.697258,"geo_status":"db","era":"江戸末期／平成22頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"29-0229","desc":"主屋北西側に南北棟で建ち、廊下で接続する。木造二階建、南面入母屋造、北面切妻造、桟瓦葺で、二階南東面に高欄付の縁を廻らす。一階の板間はもと二室の客室で、西面にトコを二所備え、旧室境に透彫欄間を飾る。落ち着いた佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010990"},{"id":"00009354","register_sub_id":"101","register_pk":"194147","name":"田村青芳園茶舗店舗兼主屋","kana":"たむらせいほうえんちゃほてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市勝南院町19-1","lat":34.67909534,"lng":135.83042688,"geo_status":"db","era":"江戸後期／昭和中期・昭和後期・平成元年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0198","desc":"奈良町の通りに東面して建つ平入町家。木造二階建、切妻造桟瓦葺、間口八メートル奥行一四・一メートルで、背面に下屋を付ける。正面は軒を出桁とし、両側に卯建を設け、二階に大きな虫籠窓を設けるなど特徴あるつくりとする。奈良の伝統的町家の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009354"},{"id":"00005024","register_sub_id":"101","register_pk":"106014","name":"辻家住宅主屋","kana":"つじけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県天理市丹波市町20","lat":34.59352904,"lng":135.83461714,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"29 － 0091","desc":"上街道沿いの角地に建つ。桁行５間，梁行５間半規模の２階建で，屋根は北を切妻造，南を入母屋造の本瓦葺とし，内部は北方床上部に２列３室を配し，２階には８畳座敷や茶室等を設ける。本２階建のたちの高い姿形は，市のたつ通りに面して際だった存在になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005024"},{"id":"00000257","register_sub_id":"101","register_pk":"101247","name":"南都銀行本店","kana":"なんとぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市橋本町16-1他","lat":34.6822217,"lng":135.82854553,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建，建築面積516㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"1997.07.15(平成9.07.15)","register_no":"29 － 0001","desc":"正面に４本のイオニア式の列柱を並べ細部に装飾を施す外観は、古典様式を簡潔にまとめた好例。昭和28年に背後に増築し、その後窓枠や内装の改修を受けたが、外観はよく保存されている。設計長野宇平治、施工大林組。古都奈良の数少ない様式建築の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000257"},{"id":"00002081","register_sub_id":"101","register_pk":"103071","name":"山田酒店（茶房長谷路）主屋","kana":"やまださけてん（さぼうはせじ）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市初瀬857","lat":34.53112793,"lng":135.90625159,"geo_status":"db","era":"文化9／大正初期増築","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0039","desc":"長谷寺への参拝路に面して建つ茶房を併設した酒店。文化８年の長谷川の氾濫後に建造された。木造つし２階建，切妻造，桟瓦葺。通りに面して店舗を構え，北側に食堂，茶の間，東側に中庭に面した和室を２室とる。江戸末建立の酒店として重厚な店構えを持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002081"},{"id":"00002438","register_sub_id":"101","register_pk":"103428","name":"池庄漆器店主屋","kana":"いけしょうしっきてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海南市黒江692","lat":34.16143,"lng":135.204636,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"30 － 0047","desc":"江戸後期より続く漆器問屋の一つで，敷地は正面が小路に，背面が黒江の中心街区の川端通りに接する。小路に面する主屋は切妻造，２階建で，背面に平屋建の角屋を延ばす。建物高が全体的に低い構成で，重厚な本瓦葺屋根をあげ，近世の町並み景観を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002438"},{"id":"00014287","register_sub_id":"101","register_pk":"509677","name":"一木旅館旧館","kana":"いちきりょかんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11071944,"lng":135.15778889,"geo_status":"db","era":"明治後期／昭和12年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0322","desc":"長保寺参詣道に所在する旅館の客室棟。二階建、入母屋造桟瓦葺、塀を挟んで参詣道に二階を見せる。本館の西に玄関棟で繋がる。一階に大小四室の続き座敷、二階に床構え付六畳と次の間六畳を配する。数寄屋風で銘木趣味のやや濃厚な意匠で新館と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014287"},{"id":"00014286","register_sub_id":"101","register_pk":"509676","name":"一木旅館玄関棟","kana":"いちきりょかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11072778,"lng":135.15790833,"geo_status":"db","era":"昭和12年頃／昭和30年頃改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0321","desc":"長保寺参詣道に所在する旅館の玄関棟。通りに開く門から石敷き路で引き込んだ前庭奥にあり、平屋建、両下造桟瓦葺で、本館と旧館を繋ぐ東西廊下と新館への渡り廊下及び水廻りで構成する。玄関土間に那智黒石を散らすほか、内外に数寄を凝らした意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014286"},{"id":"00014288","register_sub_id":"101","register_pk":"509678","name":"一木旅館新館","kana":"いちきりょかんしんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11083333,"lng":135.15785278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0323","desc":"長保寺参詣道の旅館客室棟。二階建、入母屋造桟瓦葺で、玄関棟の北に渡り廊下で繋がる。寄付、前室、床構え付き主室、広縁からなる個別客室を、一階三部屋、二階二部屋配し、落ち着いた数寄屋風意匠でまとめる。広縁は敷地背面の宮川に面して風情がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014288"},{"id":"00014285","register_sub_id":"101","register_pk":"509675","name":"一木旅館本館","kana":"いちきりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11068889,"lng":135.15797222,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0320","desc":"長保寺参詣路に南面して所在する町家で旅館を営む。平屋建、切妻造平入本瓦葺で軒が低く、東側から広い通り土間と一列二室、玄関と角屋に延びる廊下、待合等の和室二室と背面側に角屋の床構え付き続き座敷を設ける。参詣路の歴史的景観を伝える貴重な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014285"},{"id":"00014289","register_sub_id":"101","register_pk":"509679","name":"一木旅館門及び塀","kana":"いちきりょかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11066944,"lng":135.15780556,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"門 木造、杉皮葺、間口1.7m 塀 木造、瓦葺、総延長20m","structure_material":"門 木造","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0324","desc":"長保寺参詣道に南面する旅館の門塀。門は切妻造杉皮葺の腕木門で、出節の柱に両折れ板戸を建てる。土間に那智黒石を敷き込む。塀は桟瓦軒先銅板葺で、真壁造漆喰仕上に角窓を開け、腰に半割丸太を張る。数寄を凝らす意匠で参詣道に趣を与える近代和風の門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014289"},{"id":"00014079","register_sub_id":"101","register_pk":"508339","name":"大前屋旅館","kana":"おおまえやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県新宮市三輪崎一丁目293他","lat":33.68544167,"lng":135.98591667,"geo_status":"db","era":"明治36年／昭和48年改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"30 - 0317","desc":"三輪崎港の通りに北面する近代和風旅館。二階建入母屋造桟瓦葺で庇を付す。東寄に玄関を開け両脇に出格子を構え、二階の建ちが高い。内部は玄関ホールから中廊下を通して両脇に続き間座敷等を配置する。各室に縁や出窓を設け、海や通りへの眺望を確保する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014079"},{"id":"00002436","register_sub_id":"101","register_pk":"103426","name":"尾崎林太郎家住宅三階蔵","kana":"おざきりんたろうけじゅうたくさんかいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県海南市黒江598","lat":34.160969,"lng":135.204605,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積64㎡","structure_material":"土蔵造3階建","registered":"2001.10.12(平成13.10.12)","register_no":"30 － 0045","desc":"尾崎家は海上輸送の要所であった黒江川沿いの荷揚場南に位置している。三階蔵は漆器商品を収蔵し，東側道路に面した長屋門と主屋との間に建つ。東西棟の切妻造，桟瓦葺，内部は三層で，建ちも高く，商家に相応しいつくりである。上棟式の御幣より年代が判る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002436"},{"id":"00001337","register_sub_id":"101","register_pk":"102327","name":"上御殿本館","kana":"かみごてんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県田辺市龍神村龍神42-1","lat":33.95708504,"lng":135.56189866,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積197㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"30 － 0036","desc":"紀州徳川家初代頼宣公の保護を受けた温泉別荘としての由緒をもつことで知られる。明治１７年類焼後の再建になるもので，日高川を背にし，旧国道に面して建つ。紀州藩御殿の系譜をひく総２階，入母屋屋根の旅館建築で，２階に床を一段あげた「御成間」をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001337"},{"id":"00007111","register_sub_id":"101","register_pk":"108093","name":"亀屋旅館本館","kana":"かめやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県田辺市本宮町川湯1434-1","lat":33.81285088,"lng":135.77402075,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"30 － 0134","desc":"大塔川沿いの川湯温泉のほぼ中央に位置する。入母屋造桟瓦葺の木造２階建で、１階に銅板葺庇を付ける。桁行１５ｍ梁間９．０ｍ規模で、正面中央に南面して玄関を設ける。１、２階とも中廊下式で、両側に部屋を配する。風景と調和し、老舗旅館の風格を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007111"},{"id":"00014523","register_sub_id":"101","register_pk":"513937","name":"旧浦清兵衛商店店舗","kana":"きゅううらせいべえしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県有田郡広川町大字広字南市場1323他","lat":34.02657222,"lng":135.17288056,"geo_status":"db","era":"明治後期／令和4年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"30 - 0334","desc":"旧広村中心地の辻角に建つ造り酒屋の旧店舗。二階建、入母屋造本瓦葺で軒まで塗込め、壁面は黒漆喰塗仕上で重厚にみせる。内部は東を土間、西を床上とし、北西を床構付き座敷とする。大きな格子窓を二階北角に寄せた外観が地域のランドマークとなる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014523"},{"id":"00002566","register_sub_id":"101","register_pk":"103556","name":"旧葛城館","kana":"きゅうかつらぎかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県橋本市高野口町名倉1053","lat":34.3074,"lng":135.556992,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造3階建、瓦葺、建築面積113㎡","structure_material":"木造3階建","registered":"2001.11.20(平成13.11.20)","register_no":"30 － 0048","desc":"ＪＲ和歌山線高野口駅前に北面して建つ。桁行５間半，梁間５間規模の総３階建で，東西棟，入母屋造，桟瓦葺とし，正面及び東側面には銅板葺の庇を各階に廻し，屋根正面には瓦葺の千鳥破風と銅板葺の唐破風を重ねる。木造３階建和風旅館建築の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002566"},{"id":"00002087","register_sub_id":"101","register_pk":"103077","name":"旧西本組本社ビル","kana":"きゅうにしもとぐみほんしゃびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市小野町3-43","lat":34.23189997,"lng":135.16330714,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積82㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.12.04(平成12.12.04)","register_no":"30 － 0042","desc":"ＲＣ造３階建。腰を花崗岩張，２，３階をタイル張とし，玄関部にはペディメントをイオニア式柱で支えたポーティコがとりつく。立面のデザインと細部の装飾はよく均整がとれ，建設会社旧本社ビルとしての風格をもつ。設計は早大出身で西本組に勤めた岩井信一。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002087"},{"id":"00014406","register_sub_id":"101","register_pk":"511395","name":"旧堀田茶舗（立石茶屋）座敷棟","kana":"きゅうほったちゃほ（たていしちゃや）ざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字道町860-2","lat":34.03470278,"lng":135.17827778,"geo_status":"db","era":"昭和９年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0331","desc":"市街地四ツ辻に所在する商家の住居で、店舗背面北寄りに接続する東西棟。二階建、西切妻・東寄棟造で桟瓦葺、二階壁銅板張。各階二室、衣桁形板欄間や四方竹竿縁等を用いる数寄屋風和室と、二階西部屋の洋室からなる。四ツ辻の暮らしの歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014406"},{"id":"00014405","register_sub_id":"101","register_pk":"511394","name":"旧堀田茶舗（立石茶屋）店舗","kana":"きゅうほったちゃほ（たていしちゃや）てんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字道町860-2","lat":34.03468889,"lng":135.17816667,"geo_status":"db","era":"江戸末期／平成19年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0330","desc":"熊野街道と深専寺参道の四ツ辻北東角に西面するつし二階建町家。背面に便所・風呂を張り出す。切妻造本瓦葺、軒を塗込めて虫籠窓を設ける。内部は正面に幅の狭い前土間、南側を通り土間とした一列二室の小規模な店舗。四ツ辻の賑わいの歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014405"},{"id":"00014407","register_sub_id":"101","register_pk":"511396","name":"旧堀田茶舗（立石茶屋）土蔵","kana":"きゅうほったちゃほ（たていしちゃや）どぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字道町860-2","lat":34.03468333,"lng":135.17835833,"geo_status":"db","era":"江戸末期／昭和前期・平成23年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0332","desc":"四ツ辻角の商家の商品蔵で、敷地東辺の通りに妻面の竪板張壁を見せる。土蔵造二階建、切妻造桟瓦葺。内部は一階戸口廻りを土間で吹抜とし、他は板敷で各階二室に仕切る。内部の風食の程度から、頻繁な商品搬出入が分かり、湯浅の商業地としての繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014407"},{"id":"00015497","register_sub_id":"101","register_pk":"533512","name":"旧万忠金物店店舗","kana":"きゅうまんちゅうかなものてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字道町771","lat":34.03531667,"lng":135.17790833,"geo_status":"db","era":"大正3年頃／昭和前期・令和6年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積83㎡","structure_material":"木造3階建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0405","desc":"湯浅町の中心部に位置する旧金物店の店舗。熊野街道に東面して建つ木造３階建切妻造平入鉄板葺で正面は各階境に出桁庇を付し、２・３階は連続窓を開け、軒裏は黒漆喰で塗込める。1階は店舗でかつて上階は物置とした。湯浅初の木造３階建と伝える貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015497"},{"id":"00005029","register_sub_id":"101","register_pk":"106019","name":"珠数屋四郎兵衛店舗","kana":"じゅずやしろべえてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山771","lat":34.21305184,"lng":135.58637127,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、銅板葺、建築面積290㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"30 － 0080","desc":"弘法大師１１００年御遠忌に際し建設。棟梁は地元大工の阪田平造と伝える。入母屋造，銅板瓦葺の木造２階建，正面２階中央に唐破風を構える。２階道路側は参詣客の休憩室としての大広間とする。商店名とともによく知られ，地元の人々から広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005029"},{"id":"00005653","register_sub_id":"101","register_pk":"106641","name":"高垣酒造主屋","kana":"たかがきしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町小川1465","lat":34.0781656,"lng":135.2801267,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積245㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0095","desc":"敷地のほぼ中央に東西棟で建つ。桁行９間半，梁行６間，入母屋造，桟瓦葺で，西方を土間，東方床上部を２列６室とし，東南に床付きの１０畳座敷を配する。土間部の上には南北棟の入母屋造，桟瓦葺の２階を載せた独特の外観で，全体として上質のつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005653"},{"id":"00005902","register_sub_id":"101","register_pk":"106887","name":"多田家住宅（旧和中家住宅）主屋","kana":"ただけじゅうたく（きゅうわなかけじゅうたく）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中2-10-8","lat":34.19028886,"lng":135.1678938,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"30 － 0101","desc":"南北に走る明光通り商店街に西面して建つ。間口８間半，奥行４間規模，北を切妻造，南を入母屋造とした本瓦葺のつし２階建で，前面に本瓦葺の下屋を付け，内部は北を土間，南を床上部とし，南に落棟で１０畳座敷を延ばす。和歌浦の歴史的景観を伝える要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005902"},{"id":"00014919","register_sub_id":"101","register_pk":"519179","name":"辻慶進堂店舗兼主屋","kana":"つじけいしんどうてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県紀の川市名手市場193","lat":34.27552778,"lng":135.4358,"geo_status":"db","era":"昭和27年／昭和50年代改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0354","desc":"大和街道に北面する印刷業の店舗兼主屋。入母屋造二階建桟瓦葺で両袖に卯建壁を設ける。一階は西を土間とし、二階は中廊下の東西に各二室配す。二階洋室はマントルピースの左右に床と棚を組合わせるなど、数寄屋風と洋風意匠を独特に用いた和洋折衷の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014919"},{"id":"00014921","register_sub_id":"101","register_pk":"519181","name":"辻慶進堂土蔵","kana":"つじけいしんどうどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県紀の川市名手市場193","lat":34.27532778,"lng":135.435875,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0356","desc":"離れの西隣に西面して建つ道具蔵。土蔵造二階建切妻造平入桟瓦葺。外壁は白漆喰壁で南妻の拝に鏝絵で家紋を掲げ、出入口と窓に持送付庇を付し、腰は板張とする。一階は二室、二階は一室とし、小屋組は登梁を水平の繋梁で繋ぐ。離れとともに屋敷構えを構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014921"},{"id":"00014920","register_sub_id":"101","register_pk":"519180","name":"辻慶進堂離れ","kana":"つじけいしんどうはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県紀の川市名手市場193","lat":34.27533611,"lng":135.435975,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0355","desc":"矩折れ状敷地の南東奥に建つ隠居所。寄棟造東西棟桟瓦葺。北面西端に玄関、東に八畳二間の座敷を配し、南から西に縁及び廊下を廻す。座敷は床、床脇、付書院を備え、節のある太い材を用いた床柱や細い丸竹を竿縁とした船底天井を張るなど数寄屋風意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014920"},{"id":"00013320","register_sub_id":"101","register_pk":"366309","name":"橋本太次兵衛家住宅旧米穀集荷事務所","kana":"はしもとたじべえけじゅうたくきゅうべいこくしゅうかじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原195","lat":33.90305278,"lng":135.16269722,"geo_status":"db","era":"大正後期／昭和21年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"30 － 0281","desc":"新座敷が建つ敷地の道向かいで、旧熊野街道に西面して建つ。木造平屋建、寄棟造桟瓦葺妻入で、外壁は下見板張、上部を漆喰塗とする。東西に板間の洋間を二室並べ、小屋はキングポストトラス組とする。玄関庇軒先の繰形や縦長の上下窓など、洋風意匠が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013320"},{"id":"00013321","register_sub_id":"101","register_pk":"366310","name":"橋本太次兵衛家住宅土塀","kana":"はしもとたじべえけじゅうたくどべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原195","lat":33.90310556,"lng":135.16272222,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土塀、瓦葺、総延長20m","structure_material":"土塀","registered":"2020.04.03(令和2.04.03)","register_no":"30 － 0282","desc":"旧米穀集荷事務所の北側で、敷地と街路を区切る。折れ曲がり延長２０メートルの土塀で、基礎は外側が谷積、内側が切石布積で、末広がりの高い石積とする。上部壁面はモルタル洗出し仕上、鉢巻まで同様に仕上げ、桟瓦を葺く。旧熊野街道沿いの景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013321"},{"id":"00005650","register_sub_id":"101","register_pk":"106638","name":"初桜酒造主屋","kana":"はつさくらしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町中飯降85","lat":34.303116,"lng":135.533478,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積197㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0092","desc":"旧大和街道に南面する敷地の南寄りに東西棟で建つ。桁行６間，梁行６間，入母屋造，桟瓦葺，木造２階建の町家建築で，東方を土間とし，西方床上部に２列３室を配し，２階正面側に３室の続き間座敷を設ける。良材を用い，床脇柱など趣向を凝らしたつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005650"},{"id":"00004285","register_sub_id":"101","register_pk":"105275","name":"火伏医院主屋","kana":"ひぶせいいんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市橋本1-16、1-17","lat":34.31635706,"lng":135.61208473,"geo_status":"db","era":"享保6／江戸末期改造","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積101㎡","structure_material":"木造平屋一部2階建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0056","desc":"旧伊勢街道に北面して建つ。間口８間規模，切妻造，桟瓦葺，平入のつし２階建町家で，西側を中土間とし，東側の２室続きの座敷部は落棟で，江戸末期の改築とみられる。棟札から年代の判明する町家で，当地方町家の指標的建築として貴重","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004285"},{"id":"00004287","register_sub_id":"101","register_pk":"105277","name":"前田家住宅主屋","kana":"まえだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市高野口町名倉392-1","lat":34.3051796,"lng":135.55573388,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0058","desc":"通りに北面して建つ。桁行６間梁間４間，切妻造，桟瓦葺のつし２階建町家で，軒下まで塗込めて重厚な外観をつくり，正側面３面に半間，背面に１間の下屋庇を廻す。内部は西側を中土間，東側床上部は四間取りとし，土間上部背面側に煙出しを揚げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004287"},{"id":"00006386","register_sub_id":"101","register_pk":"107369","name":"山本勝之助商店事務所","kana":"やまもとかつのすけしょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.15996247,"lng":135.25991665,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0119","desc":"シュロ皮商の店舗として建設。国道に南面する間口３間、奥行８間の木造２階建で、寄棟造桟瓦葺の東西棟の裏に切妻造本瓦葺の南北棟が続く。南面は１、２階ともガラス窓とし、東面南端に戸口を開く。１階表の事務所には鉄柱を用いる。外壁の黒漆喰が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006386"},{"id":"00006387","register_sub_id":"101","register_pk":"107370","name":"山本勝之助商店店蔵一","kana":"やまもとかつのすけしょうてんみせぐらいち","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.15998659,"lng":135.25981705,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積128㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0120","desc":"事務所の西に並ぶ土蔵造２階建の商品倉庫。桁行７間、梁間４間の南北棟で、国道に妻を見せる。切妻造桟瓦葺で、東平側に瓦葺庇をつけて蔵前とする。外壁は白漆喰塗で、腰に鉄板を張り、２階には小窓を穿つ。小屋組は登梁。歴史的街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006387"},{"id":"00006389","register_sub_id":"101","register_pk":"107372","name":"山本勝之助商店店蔵三","kana":"やまもとかつのすけしょうてんみせぐらさん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井479-1","lat":34.159744,"lng":135.259903,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積119㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0122","desc":"事務所の向かいに建つ土蔵造２階建である。桁行８間、梁間３間の東西棟で、切妻造桟瓦葺とし、北に吹放ちの瓦葺庇をつけて、３箇所に戸口を開く。１階は板床。束立の和小屋である。外壁は白漆喰塗で、妻は鉢巻に造り、軒は垂木形に塗り込めて変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006389"},{"id":"00006388","register_sub_id":"101","register_pk":"107371","name":"山本勝之助商店店蔵二","kana":"やまもとかつのすけしょうてんみせぐらに","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井479-1","lat":34.15979319,"lng":135.25966646,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0121","desc":"店蔵一と国道を挟んで向かいに建つ土蔵造２階建である。桁行５間、梁間２間半の南北棟で、切妻造桟瓦葺。東に瓦葺庇をつけて蔵前とする。外壁は白漆喰塗で、腰は竪板張。１階は板床とする。束立の和小屋で、野地は割竹の小舞である。妻の屋号がアクセント。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006388"},{"id":"00013445","register_sub_id":"101","register_pk":"368530","name":"和歌山県建築士会館","kana":"わかやまけんけんちくしかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"和歌山県","address":"和歌山県和歌山市卜半町38","lat":34.23260833,"lng":135.16998889,"geo_status":"db","era":"昭和41年／平成25年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造3階地下１階建、建築面積184㎡","structure_material":"鉄筋コンクリート造3階地下１階建","registered":"2020.08.17(令和2.08.17)","register_no":"30 － 0283","desc":"和歌山城北の市堀川北岸に建つ。正面一階の壁面を内側に立て、上階の平滑な壁を鉄筋コンクリート造の桁で受けて浮遊感を出す。正面のタイル貼壁面に窓を規則正しく並べ、側壁をコンクリート打放しにして正面性を強調し、内樋により端正な立面に仕立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013445"},{"id":"00002057","register_sub_id":"101","register_pk":"103047","name":"石田家住宅主屋","kana":"いしだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市神足2-13-10","lat":34.919952,"lng":135.69841,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0080","desc":"市内を縦貫する旧西国街道に東面して建つ。切妻造，桟瓦葺，つし２階の町家で，北東南３面に桟瓦葺の庇を廻す。内部は南に通り庭を，北に２列６室を配する。神足村旧家の商家を石田家先代が購入したもので，茶の小売業を営みつつ旧街道の佇まいを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002057"},{"id":"00007226","register_sub_id":"101","register_pk":"108208","name":"伊藤喜商店旧店舗兼主屋","kana":"いとうきしょうてんきゅうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区松原通大和大路東入二丁目轆轤町100","lat":34.99765093,"lng":135.77404872,"geo_status":"db","era":"大正15頃／平成19改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積145㎡、塀付","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0311","desc":"松原通に北面して建つ木造２階建の平入町家で醤油を商った。間口５間半で、切妻屋根を桟瓦葺とし、銅板葺庇がつく。背後に風呂と便所が突出する。正面１階は戸口の両側窓に円形断面の格子を入れ、腰を石貼とする。２階は格子窓。大正期の大型町家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007226"},{"id":"00002947","register_sub_id":"101","register_pk":"103937","name":"今林家住宅糸蔵","kana":"いまばやしけじゅうたくいとぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53615816,"lng":135.19186918,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0137","desc":"敷地の北西部に主屋に接しながら，東西棟で建つ。丁寧なつくりに加えて敷地内最大規模の蔵で，糸問屋として機能上かつ建築上の中心的建造物。切妻造，妻入で，梁間を桁行よりも長くとり，２階に２つの開口部を左右対称に設けた大きな妻面を造るのが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002947"},{"id":"00007511","register_sub_id":"101","register_pk":"108493","name":"今林家住宅旧生糸蔵","kana":"いまばやしけじゅうたくきゅうきいとぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53615481,"lng":135.19187467,"geo_status":"db","era":"安政5／平成20改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"26 － 0333","desc":"旧店舗の後方に建つ。桁行５．８ｍ梁間３．９ｍ、土蔵造２階建、切妻造桟瓦葺。外部漆喰塗で腰を竪板張とし、南面西寄りを出入口として両開戸を吊り、瓦葺の庇を掛ける。明治初年には内部に縮緬織機を据えて機織りをしたと伝え、部材の一部を棟木に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007511"},{"id":"00007510","register_sub_id":"101","register_pk":"108492","name":"今林家住宅旧店舗","kana":"いまばやしけじゅうたくきゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53605868,"lng":135.19185932,"geo_status":"db","era":"江戸末期／昭和27頃・平成20改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積80㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"26 － 0332","desc":"主屋の西に高塀を介して南面して並び建つ。間口９．８ｍ奥行８．２ｍ、木造２階建、切妻造桟瓦葺。当初は東のトオリニワと、食違い四間取を基本とする間取。正面は真壁造で、２階両袖に卯建を付け、出格子を構える。宮津城下の商家町の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007510"},{"id":"00002945","register_sub_id":"101","register_pk":"103935","name":"今林家住宅主屋","kana":"いまばやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53607589,"lng":135.19193657,"geo_status":"db","era":"明治25／大正期増築","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積261㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0135","desc":"市中心部にある。木造２階建，切妻造，平入で，通り側に半間幅の下屋庇を設ける。正面には平格子・出格子を構え，玄関戸口に引上式大戸を残す。棟の東方には越屋根を設け，軒高を低くした２階西方には袖卯建を付ける。旧宮津城下を代表する町家建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002945"},{"id":"00000697","register_sub_id":"101","register_pk":"101687","name":"エンマ（旧村井銀行祇園支店）","kana":"えんま（きゅうむらいぎんこうぎおんしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区四条通大和大路東入祇園町南側573-5","lat":35.00365368,"lng":135.77462516,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積186㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0019","desc":"たばこ王として知られた村井家のお抱え建築家的存在であった吉武長一による一連の村井銀行支店シリーズのひとつ。アメリカ仕込みの古典主義建築の作風がよく示されており，パラペットのバラストレードなどの細部もよく残されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000697"},{"id":"00015032","register_sub_id":"101","register_pk":"529310","name":"岡墨光堂奥蔵","kana":"おかぼっこうどうおくのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町113","lat":35.00951111,"lng":135.76532778,"geo_status":"db","era":"明治20年","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0674","desc":"主屋の東に建つ家財蔵。土蔵造２階建切妻造平入本瓦葺で、西面を戸口とし下屋を付す。各階一室の板敷とし、南辺に階段を設け、小屋組は束立の和小屋。外壁は漆喰塗仕上とし、腰は竪板張。一階西面の窓と戸口に掛子塗扉を吊り、外観重厚で丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015032"},{"id":"00015031","register_sub_id":"101","register_pk":"529309","name":"岡墨光堂表蔵","kana":"おかぼっこうどうおもてのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町113","lat":35.00959722,"lng":135.76509167,"geo_status":"db","era":"明治中期／大正11年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0673","desc":"主屋の北、通りに面して建ち、表具などを仮置する土蔵。土蔵造２階建切妻造妻入本瓦葺。外壁は漆喰塗仕上で腰に竪板を高く張り、西面南寄りに窓を開ける。南面戸口に厚い鉄扉を吊り、職場と接続する。軒に鉢巻を廻らした重厚な外観が通りの歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015031"},{"id":"00015029","register_sub_id":"101","register_pk":"529307","name":"岡墨光堂主屋","kana":"おかぼっこうどうおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町113","lat":35.00950833,"lng":135.76520278,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積193㎡、西面北塀付","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0671","desc":"富小路通に西面して建つ表具業の主屋。表屋造とし、2階建切妻造平入桟瓦葺の事務所棟の東に居室棟を配し、渡廊下で接続する。事務所棟には残月床の座敷やマントルピースを備えた洋室など、上質な客間を配す。通りに面した大きな虫籠窓が時代相を示す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015029"},{"id":"00015030","register_sub_id":"101","register_pk":"529308","name":"岡墨光堂職場","kana":"おかぼっこうどうしょくば","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町113","lat":35.0096,"lng":135.76516389,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積61㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0672","desc":"主屋居室棟の北に建ち表装などを行う作業場。2階建鉄筋コンクリート造切妻造鉄板葺の東西棟で、西端部は平面撥形とし、表の蔵に接続する。一階は二室、二階は一室の板敷で、小屋組は木造のキングポスト・トラス。鉄扉を吊った窓が並ぶ厳重なつくりの作業場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015030"},{"id":"00016677","register_sub_id":"101","register_pk":"579161","name":"喫茶ソワレ","kana":"きっさそわれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市下京区四条通小橋西入真町96-4","lat":35.004178,"lng":135.770337,"geo_status":"db","era":"昭和23年頃／昭和35年頃改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階建、人工スレート葺、建築面積36㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"26 - 0742","desc":"高瀬川の西岸に位置する喫茶店。二階建切妻造妻入人工スレート葺で、正面に円錐屋根の塔屋を載せる。内部は柱や梁などナグリ仕上とし、腰壁は葡萄などの木彫で濃密に装飾する。全体的に工芸的なつくりの喫茶店で、青色の内部照明が幻想的な雰囲気を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016677"},{"id":"00011524","register_sub_id":"101","register_pk":"210474","name":"旧鴻池銀行七条支店","kana":"きゅうこうのいけぎんこうしちじょうしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市下京区七条通新町西入夷之町704","lat":34.98942194,"lng":135.75612611,"geo_status":"db","era":"昭和2年／平成20年頃改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階一部地下1階建、建築面積164㎡","structure_material":"鉄筋コンクリート造2階一部3階一部地下1階建","registered":"2017.05.02(平成29.05.02)","register_no":"26-0513","desc":"七条通に南面する鉄筋コンクリート造二階一部三階建。正面に縦長のアーチ窓を並べ、隅石を表し、壁頂にロンバルド帯を飾る等ロマネスクを基調としつつ、玄関庇の持送や内部柱の柱頭まわりなどは幾何模様で装飾密度を高める。意匠華やかな昭和初期の銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011524"},{"id":"00015486","register_sub_id":"101","register_pk":"533501","name":"旧福知山信用金庫本店","kana":"きゅうふくちやましんようきんこほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府福知山市字中ノ21","lat":35.29974444,"lng":135.12481389,"geo_status":"db","era":"昭和3年／平成26年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積212㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0701","desc":"福知山城跡北西の市街地の角地に建つ旧銀行の店舗。二階建鉄筋コンクリート造で外壁モルタル塗仕上、腰は花崗岩切石貼。南西隅切部を中軸とする左右対称の簡明な立面構成で、出入口の庇や半円形窓台をアクセントとする。近代の福知山の繁栄を伝える銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015486"},{"id":"00003443","register_sub_id":"101","register_pk":"104433","name":"旧藤ノ森湯","kana":"きゅうふじのもりゆ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野東藤ノ森町11-1","lat":35.03759083,"lng":135.74688628,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0157","desc":"船岡温泉の東方，鞍馬口通に面して建つ。脱衣場，浴場・釜場からなり，脱衣場棟２階に和室を設ける。木造だが，浴場左右と釜場境の壁は木骨煉瓦造とする。正面出入口に唐破風を付け，内外を装飾タイル張とするなど，随所に意匠を凝らす。現在飲食店等に転用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003443"},{"id":"00002051","register_sub_id":"101","register_pk":"103041","name":"キンシ正宗堀野記念館（旧堀野家本宅）主屋","kana":"きんしまさむねほりのきねんかん（きゅうほりのけほんたく）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区堺町通二条上る亀屋町172","lat":35.014095,"lng":135.763031,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0074","desc":"堺町通に東面して建つ間口６間半規模のやや大型の町家。主体部は南北棟，切妻造，桟瓦葺で，正面は階下に２本切子格子，階上に虫籠窓を並べ，黒漆喰で仕上げる。内部は２段２列に室を配置し，階上に書院座敷，階下に数寄屋風座敷を設ける点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002051"},{"id":"00002289","register_sub_id":"101","register_pk":"103279","name":"近又主屋","kana":"きんまたしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区御幸町通四条上る大日町407","lat":35.00475578,"lng":135.7662771,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積110㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0081","desc":"近江出身の近江屋又八が創業した商人宿。近又は屋号で，明治３６年頃に現在地に移った。御幸町通に東面して建つ２階建・平入・桟瓦葺の町家建築で，１階北半と２階に客室を設ける。数寄屋風の意匠でまとめられ，床や棚，窓，欄間など変化に富んだ造形を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002289"},{"id":"00002290","register_sub_id":"101","register_pk":"103280","name":"近又離れ","kana":"きんまたはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市中京区御幸町通四条上る大日町407","lat":35.00476368,"lng":135.76622734,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0082","desc":"主屋の後方に中庭を挟んで連なり，昭和３年の御大礼に際して建設されたという。２階建，切妻造・桟瓦葺で，１階・２階とも中廊下とし，上手２室，下手１室の客室を配する。主屋と同じく数寄屋風で，障子等の建具や板欄間など細部に凝ったつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002290"},{"id":"00010838","register_sub_id":"101","register_pk":"201673","name":"壽ビルディング","kana":"ことぶきびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市下京区西木屋町通松原上る三丁目市之町251-7他","lat":35.00167,"lng":135.769175,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積159㎡、塔屋付","structure_material":"鉄筋コンクリート造5階建","registered":"2015.11.17(平成27.11.17)","register_no":"26 ‐ 0494","desc":"河原町通に面して建つ鉄筋コンクリート造五階建。内外観は簡素な意匠を基本としつつ、正面玄関や階段にアール・デコ風意匠を取入れ、一階外壁の石張や柱形頂部にアカンサスなどの様式主義的要素を備える。京都中心部に残る昭和初期の事務所ビルとしても希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010838"},{"id":"00000298","register_sub_id":"101","register_pk":"101288","name":"SACRA（旧不動貯金銀行京都支店）","kana":"さくら（きゅうふどうちょきんぎんこうきょうとしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区三条通富小路西入中之町20","lat":35.00872215,"lng":135.76487264,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木骨煉瓦造地上3階地下1階建，銅板葺，建築面積232㎡","structure_material":"木骨煉瓦造地上3階地下1階建","registered":"1997.09.03(平成9.09.03)","register_no":"26 － 0008","desc":"木骨煉瓦造，地上３階地下１階建で，屋根を銅板葺とする旧銀行の建物。全体に装飾豊かな洋風の意匠を持ち，１階部分のストライプ模様や正面中央の円形装飾等に代表されるように，細部に幾何学的な形態を用いてまとめる点に時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000298"},{"id":"00008142","register_sub_id":"101","register_pk":"132583","name":"清輝樓","kana":"せいきろう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府宮津市字魚屋937他","lat":35.53781659,"lng":135.19500851,"geo_status":"db","era":"明治34年／明治後期・大正前期・大正13年増築・昭和中期改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積683㎡","structure_material":"木造2階一部3階建","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0343","desc":"当初は宮津湾に面した位置に建ち、建築面積６８３㎡、木造３階建、入母屋造桟瓦葺で、海側は開放的なつくりとする。東面の中央部を玄関とし、海側の北・西側に客室を配し、南側３階に百五畳敷の大広間をもつ広間棟を建てる。天橋立観光を支えてきた旅館である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008142"},{"id":"00001395","register_sub_id":"101","register_pk":"102385","name":"俵屋旅館","kana":"たわらやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区麸屋町通姉小路上る中白山町280","lat":35.0088436,"lng":135.76891839,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積283㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"26 － 0048","desc":"京都に現存する最古の旅館として知られる。禁門の変で焼失の後に再建された木造２階建の建物。玄関は麸屋町通りに面し，敷地の中には複数の中庭・外庭が全客室から見えるように配置される。洗練された数寄屋風建築に優雅さと風格が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001395"},{"id":"00013420","register_sub_id":"101","register_pk":"368505","name":"茶又旅館主屋及び離れ","kana":"ちゃまたりょかんおもやおよびはなれ","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府舞鶴市字本小字本町38","lat":35.44845,"lng":135.32638333,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積207㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0607","desc":"旧田辺城下の町人地、竹屋町通に東面して建つ。木造二階建、桟瓦葺で、主屋の背面に離れが建ち、接続部を介して一体となる。外観は朱色の壁と二階の高欄付窓が特徴的で、主屋の一階には帳場、厨房や住居部、二階及び離れは客室を配す。戦後復興した旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013420"},{"id":"00013421","register_sub_id":"101","register_pk":"368506","name":"茶又旅館土蔵","kana":"ちゃまたりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府舞鶴市字本小字本町38他","lat":35.44850833,"lng":135.32626389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0608","desc":"敷地の背面北寄り、高野川に面して建つ旅館の土蔵。土蔵造二階建、切妻造桟瓦葺東西棟で、東面の南隅に入口を設け、西面に各階二箇所の窓を穿つ。内部は各階一室で、一階は土間、二階は板敷とし、家財蔵として使用した。川沿いの景観を形成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013421"},{"id":"00013422","register_sub_id":"101","register_pk":"368507","name":"茶又旅館門及び塀","kana":"ちゃまたりょかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府舞鶴市字本小字本町38","lat":35.44847222,"lng":135.32644167,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"門 木造、瓦葺、間口2.0m、塀 木造、瓦葺、総延長13m","structure_material":"門 木造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0609","desc":"主屋の前面、道路境界に沿って建つ。門を塀のやや南寄りに開き、屋根は塀より一段高くする。柱上に棟木を渡し腕木で桁を支え、内側に荒い格子の両引分戸を建てる。塀は壁を朱色の漆喰塗腰高の竪板張とし、要所に飾格子付小窓を設ける。通りの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013422"},{"id":"00008141","register_sub_id":"101","register_pk":"132582","name":"茶六本館","kana":"ちゃろくほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府宮津市字魚屋866他","lat":35.53687273,"lng":135.1918386,"geo_status":"db","era":"大正期／昭和10年増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造3階建、瓦葺、建築面積259㎡","structure_material":"木造3階建","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0342","desc":"通りに西面して建つ木造３階建の旅館建築で、建築面積２５９㎡、屋根は桟瓦葺である。切妻造平入の当初部分と、入母屋造妻入の昭和増築部からなる特徴的な立面で、１階に出格子を付け、上階窓の高欄では室境に脇障子風の仕切りを設けるなど瀟洒な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008141"},{"id":"00009189","register_sub_id":"101","register_pk":"164742","name":"月見館本館","kana":"つきみかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市伏見区桃山町泰長老160-4他","lat":34.92838535,"lng":135.77030348,"geo_status":"db","era":"昭和8年／昭和中期・昭和40年・平成期改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造地上3階地下1階建、瓦葺、建築面積679㎡","structure_material":"木造地上3階地下1階建","registered":"2012.02.23(平成24.02.23)","register_no":"26 - 0396","desc":"宇治川の北岸に位置する。木造3階地下1階建、建築面積679平方メートルで、東西棟と南北棟がＬ字形の主棟を構成する。屋根は桟瓦葺で千鳥破風を飾る。各階ともに、南面に窓を連続させ、観月の名所と知られる宇治川に望む。昭和初頭の旅館の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009189"},{"id":"00016676","register_sub_id":"101","register_pk":"579160","name":"鶴清","kana":"つるせ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区木屋町通松原下る二丁目下材木町451他","lat":34.99676,"lng":135.767826,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造地上3階地下1階建、瓦葺一部銅板葺、建築面積607㎡","structure_material":"木造地上3階地下1階建","registered":"2026.07.09(令和8.07.09)","register_no":"26 - 0741","desc":"鴨川右岸に建つ木造３階建の旅館。全体コの字平面で木屋町通りに面して玄関を構え、鴨川に面して入母屋造の大屋根の軒に切妻破風を飾る。３階大広間は148畳半で折上格天井を張る。小屋組は鉄骨のキングポスト・トラス。鴨川沿いの風情をつくる大規模旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016676"},{"id":"00014628","register_sub_id":"101","register_pk":"515170","name":"富美代大広間棟","kana":"とみよおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区大和大路通四条上る二筋目東入末吉町103他","lat":35.00456944,"lng":135.77331667,"geo_status":"db","era":"昭和9年／昭和中期増築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"26 - 0653","desc":"主屋北側に建つ大広間棟。切妻造桟瓦葺の東西棟二階建で南は主庭、北は奥庭に臨む。一階は東に水廻り、西に座敷を配して北に入側縁を付す。二階は二間続きの大広間で西に床構え、北と南に入側縁を付す。大宴会も可能とした近代の時代相を良く示す大広間棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014628"},{"id":"00014627","register_sub_id":"101","register_pk":"515169","name":"富美代主屋","kana":"とみよおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区大和大路通四条上る二筋目東入末吉町103他","lat":35.0045,"lng":135.77334444,"geo_status":"db","era":"大正4年／昭和50年頃改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積207㎡","structure_material":"木造2階一部3階建","registered":"2023.08.07(令和5.08.07)","register_no":"26 - 0652","desc":"祇園北側の通りに南面する茶屋。主体部は二階建切妻造平入桟瓦葺で、北へ廊下を延ばして大広間棟と接続する。東の通り土間中央を玄関とし、西の床上部は坪庭廻りに中小の座敷を配する。伝統的外観ながら、各室への動線や採光に配慮した近代らしい茶屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014627"},{"id":"00003993","register_sub_id":"101","register_pk":"104983","name":"鳥彌三主屋","kana":"とりやさしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市下京区西石垣通四条下る斎藤町136他","lat":35.00209124,"lng":135.7703241,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積136㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"26 － 0163","desc":"鴨川右岸，西石垣通に西面する木造２階建の料亭。桁行７間梁間５間半の切妻造，平入で，左手２間分の大棟がわずかに低い。１階の通り土間沿いを厨房とし，２階を中心に大小の客間を配す。出格子や２階縁の格子組手摺など，多彩な格子が趣ある外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003993"},{"id":"00003995","register_sub_id":"101","register_pk":"104985","name":"鳥彌三新座敷","kana":"とりやさしんざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市下京区西石垣通四条下る斎藤町136他","lat":35.00201935,"lng":135.77039502,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"26 － 0165","desc":"主屋の東裏手，中庭を介して，鴨川に面して建つ。南に中二階が続き，主屋とは２階南端の渡り廊下で接続する。１階は客室２室の間に土間通路を開き，夏季には川岸に仮設したユカへ至る。２階は広間で，川側に腰高の縁を設ける。鴨川縁の景観の一要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003995"},{"id":"00003994","register_sub_id":"101","register_pk":"104984","name":"鳥彌三中二階","kana":"とりやさちゅうにかい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市下京区西石垣通四条下る斎藤町136他","lat":35.00197222,"lng":135.77036402,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"26 － 0164","desc":"主屋の東裏手，鴨川に面して建つ。桁行１間半梁間２間の切妻造，桟瓦葺。新座敷に接続し，中庭から階段を昇った中２階高に６畳室を設け，妻側に奥行の浅いトコ，タナを備え，川側には腰高に縁を付ける。新座敷と軒高を違え，川岸の外観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003994"},{"id":"00001283","register_sub_id":"101","register_pk":"102273","name":"冨田屋表蔵","kana":"とんだやおもてぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02736617,"lng":135.74889004,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建，瓦葺，建築面積35㎡","structure_material":"土蔵造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0042","desc":"主屋と並び、街路に面して建つ土蔵。角地であるため妻面と平面を街路に見せている。街路側には出入り口を設けず、腰から下を一枚板で飾る特徴的な外観を持つ。現在は内部が居室として利用され、角地に建つこともあってランドマーク的な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001283"},{"id":"00001281","register_sub_id":"101","register_pk":"102271","name":"冨田屋主屋","kana":"とんだやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02742869,"lng":135.74882248,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造２階建，瓦葺，建築面積117㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0040","desc":"近世末期まで伏見で両替商を営んでいた所有者が、明治18年頃にこの地に移り織物問屋を創業して建てた建築である。間口約５間、奥行７間の大規模な表屋造で、明治期に京都市内に作られた大規模商家建築の好例ということができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001281"},{"id":"00001284","register_sub_id":"101","register_pk":"102274","name":"冨田屋中蔵","kana":"とんだやなかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02744942,"lng":135.74866183,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造２階建，瓦葺，建築面積17㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0043","desc":"敷地の北端中央に立つ二階建ての土蔵。年代を示す資料はないが主屋と同時期と思われる。東の主屋側に扉を開き縁を廻して主屋、離れと連絡している。入口の上部には小規模ではあるが幾何学的模様の鏝絵を設けるなど、デザインにも工夫の跡が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001284"},{"id":"00001282","register_sub_id":"101","register_pk":"102272","name":"冨田屋離れ","kana":"とんだやはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02739938,"lng":135.74859607,"geo_status":"db","era":"昭和10代","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積89㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0041","desc":"昭和１０年代に敷地が西側に拡張されたのを受けて建築された。次の間を伴う離れ座敷と、応接間、茶室から構成され、南側に庭に面して縁を廻す。北側で宝蔵、中蔵と接しており、上層商家の建築構成を示すものとして欠くことのできないものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001282"},{"id":"00001285","register_sub_id":"101","register_pk":"102275","name":"冨田屋宝蔵","kana":"とんだやほうぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02745242,"lng":135.74855,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積26㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0044","desc":"昭和１０年の敷地拡張とほぼ同時に建築された土蔵である。中蔵と同じく東面に入口を設けている。扉の内側には屋号である富田屋を示す装飾を設け、扉上部には「宝蔵」と記している。明治期の上層商家の屋敷構成を知る上で欠くことのできない建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001285"},{"id":"00006544","register_sub_id":"101","register_pk":"107527","name":"中村治男家住宅主屋","kana":"なかむらはるおけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区室町通寺之内上る三丁目上柳原町117","lat":35.03542697,"lng":135.75834938,"geo_status":"db","era":"明治後期／昭和8改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積151㎡","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0262","desc":"街路に西面して間口３間半の表屋を建て，坪庭を介して間口６間の居住棟を並置する表屋造の町家である。表屋の１階正面は右手に大戸，左手に出格子を設け，２階に虫籠窓を開く。居住棟は１・２階とも背面に８畳座敷と６畳次の間を設ける。京町家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006544"},{"id":"00001286","register_sub_id":"101","register_pk":"102276","name":"西島家住宅主屋","kana":"にしじまけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区車屋町通夷川上る少将井御旅町352","lat":35.01566845,"lng":135.7602659,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造２階建，瓦葺，建築面積119㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0045","desc":"街路に東面して建つ中規模の町屋である。間口４間、奥行７間半の規模を持ち、１階の格子と犬矢来、２階の虫籠窓が外観を特徴づけている。通り土間を設けるなど標準的な表屋造の構成を示しており、明治期の商家の様子を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001286"},{"id":"00001287","register_sub_id":"101","register_pk":"102277","name":"西島家住宅土蔵","kana":"にしじまけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市中京区車屋町通夷川上る少将井御旅町352","lat":35.015705,"lng":135.760452,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積33㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0046","desc":"敷地の最も奥側、東端に建つ。妻面の大半を板張りとするほかは漆喰壁とし、西側に庇をさしかけて蔵前とする。桁行４間の規模を持ち、建ちが高いのが特徴。家伝によれば元治の大火以前の建築とされるが、少なくとも主屋以前の建造になる蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001287"},{"id":"00000357","register_sub_id":"101","register_pk":"101347","name":"日本生命京都三条ビル旧棟（旧日本生命京都支店）","kana":"にほんせいめいきょうとさんじょうびるきゅうとう（きゅうにほんせいめいきょうとしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区三条通高倉東入桝屋町75","lat":35.00876549,"lng":135.76390305,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造2階建，銅板葺，建築面積65㎡","structure_material":"煉瓦造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"26 － 0009","desc":"洋風の近代建築が多く立ち並ぶ三条通りに面して建つ。現在残るのは，明治４５年に着工，大正３年に竣工した社屋の通りに面した塔屋を含む１スパン部分である。設計は辰野片岡建築事務所で，外壁を石張りにする外観には，その作風がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000357"},{"id":"00003681","register_sub_id":"101","register_pk":"104671","name":"パビリオンコート（旧山中合名会社美術館）門","kana":"ぱびりおんこーと（きゅうやまなかごうめいがいしゃびじゅつかん）もん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区粟田口三条坊町14-2","lat":35.00792879,"lng":135.78264874,"geo_status":"db","era":"大正元／平成14移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、鉄板葺、間口2.0m","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"26 － 0160","desc":"大正元年に，現在地の南側隣接地に離れ等と同時に建てられた。寺院等の旧材を利用して建てられた腕木門形式の門で，扉は七宝文装飾の両折戸とする。各部材は装飾・風蝕度合いなどから複数の建築から集められたと思われ，一部に鉄材も用いられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003681"},{"id":"00003679","register_sub_id":"101","register_pk":"104669","name":"パビリオンコート（旧山中合名会社美術館）洋館","kana":"ぱびりおんこーと（きゅうやまなかごうめいがいしゃびじゅつかん）ようかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区粟田口三条坊町14-2","lat":35.00805607,"lng":135.78238924,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造地上2階地下1階建、建築面積198㎡","structure_material":"煉瓦造地上2階地下1階建","registered":"2003.12.01(平成15.12.01)","register_no":"26 － 0158","desc":"古美術品の展示・収蔵施設として建てられた。設計は池村元之助，施工は清水組である。構造は壁体を煉瓦積とし，床をＲＣ造の梁とスラブでつくる。外観は昭和１１年に改修され，地上階部分がタイル貼となっている。ＲＣを用いた初期の建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003679"},{"id":"00003680","register_sub_id":"101","register_pk":"104670","name":"パビリオンコート（旧山中合名会社美術館）和館","kana":"ぱびりおんこーと（きゅうやまなかごうめいがいしゃびじゅつかん）わかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区粟田口三条坊町14-2","lat":35.00793107,"lng":135.78257046,"geo_status":"db","era":"明治37／昭和42移築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"26 － 0159","desc":"当初古美術品の陳列施設として建てられたものを，昭和４２年に現在地に移築したもの。木造平屋建，桟瓦葺で，舟肘木を用い，窓上部に菱形格子を巡らす。南側面上部は蟇股や欄間彫刻を飾る。現在では内部を改装し，喫茶店等に活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003680"},{"id":"00011149","register_sub_id":"101","register_pk":"205256","name":"林家住宅主屋","kana":"はやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区今小路通七本松西入二丁目東今小路町751-4他","lat":35.029564,"lng":135.737213,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0500","desc":"間口四間奥行約五間半で、切妻造平入の総二階建。正面中央の三畳間から土間や居室部を経ずに離れと結び、二階の四畳半板間は踊りの舞台も兼ねるなど、お茶屋建築の特色ある平面構成である。二階の座敷はそれぞれ松と鶴を主題に意匠を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011149"},{"id":"00011150","register_sub_id":"101","register_pk":"205257","name":"林家住宅離れ","kana":"はやしけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区今小路通七本松西入二丁目東今小路町752-5他","lat":35.029413,"lng":135.73721,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造一部土蔵造平屋建、瓦葺、建築面積55㎡","structure_material":"木造一部土蔵造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0501","desc":"主屋背面に渡廊下を介して建つ。物置、納戸部分と客用の居室に分かれ、居室部分は五畳座敷と四畳半茶室を雁行させ、主屋との間の庭を眺めることができる。納戸部分は土蔵造。茶室を網代張に竿縁を放射状に配した傘天井とするなど、数寄屋風にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011150"},{"id":"00014186","register_sub_id":"101","register_pk":"508816","name":"柊家旅館本館及び塀","kana":"ひいらぎやりょかんほんかんおよびへい","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区麩屋町通姉小路上る中白山町274他","lat":35.01045556,"lng":135.76556111,"geo_status":"db","era":"明治前期／昭和28年増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造２階建、瓦葺、建築面積862㎡ 塀 木造、瓦葺、総延長40m","structure_material":"木造２階建","registered":"2022.02.17(令和4.02.17)","register_no":"26-0645","desc":"幕末大火後に建設された旅館で、増築による複雑な平面をもつ。入口は路地風に設え、玄関ホールから北と西へ廊下を延ばして客室を配す。客室はすべて数寄屋を基調とし、上下階で同平面となる二室も意匠を違えて趣を凝らす。中心市街の老舗旅館の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014186"},{"id":"00001117","register_sub_id":"101","register_pk":"102107","name":"富士ラビット","kana":"ふじらびっと","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区七条通新町西入夷之町721","lat":34.98911596,"lng":135.75660971,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造地上３階地下１階建，建築面積119㎡","structure_material":"鉄筋コンクリート造地上３階地下１階建","registered":"1999.06.07(平成11.06.07)","register_no":"26 － 0037","desc":"京都で自動車販売の草分けといわれる日光社の社屋として建てた３階建の商業ビル。社名の日光を象ったといわれる塔屋の意匠や古典的な柱のオーナメント、１階正面の自動車の描かれたステンドグラスなど様々な要素が混じり合った建物として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001117"},{"id":"00003441","register_sub_id":"101","register_pk":"104431","name":"船岡温泉旧船岡楼","kana":"ふなおかおんせんきゅうふなおかろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区紫野南舟岡町82-1","lat":35.0369269,"lng":135.74448948,"geo_status":"db","era":"大正12頃／昭和5改造","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0155","desc":"脱衣場，浴場の西方に隣接して建つ。木造，２階建で，玄関部，主棟，北棟からなる。主棟１階に小間，２階に広間を取り，北棟１，２階にも座敷を配す。目立った装飾はないが，客室床・棚回りや欄間，縁高欄等に瀟洒な意匠を凝らし旅館建築らしい佇まいを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003441"},{"id":"00003442","register_sub_id":"101","register_pk":"104432","name":"船岡温泉旧理髪店","kana":"ふなおかおんせんきゅうりはつてん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区紫野南舟岡町82-1","lat":35.03709328,"lng":135.7447169,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0156","desc":"脱衣場北東に通りに面して建つ。木造，２階建で，正側面の２階壁面をモルタル塗で高く立ち上げたいわゆる看板建築。温泉の付属施設で，１階の表側に土間の店舗，その背後と２階に和室を配す。内部腰回りの装飾タイル，正側面壁頂部の蛇腹などに意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003442"},{"id":"00003439","register_sub_id":"101","register_pk":"104429","name":"船岡温泉脱衣場","kana":"ふなおかおんせんだついじょう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区紫野南舟岡町82-1","lat":35.03700838,"lng":135.7446409,"geo_status":"db","era":"大正12／昭和3改造","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0153","desc":"料理旅館船岡楼の付属浴場として建設された施設の１つ。木造２階建で，１階は表に玄関・番台，奥に脱衣場を配し，２階に和室２室を取る。欄間・天井に奇抜な木彫を飾る内部や，昭和３年新設の軒唐破風のある鞍馬口通側外観など，市民に親しまれた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003439"},{"id":"00003440","register_sub_id":"101","register_pk":"104430","name":"船岡温泉浴場","kana":"ふなおかおんせんよくじょう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野南舟岡町82-1","lat":35.03687224,"lng":135.74468214,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積121㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0154","desc":"創業当初の煉瓦造浴場を建て替えたもの。ＲＣ造，平屋建で，脱衣場に続く廊下と男女浴場（後方は旧焚場）からなる。一段切上げた採光部に丸窓を明け，千本鞍馬口にあった菊水橋の石造欄干を転用し，内部を装飾タイルで飾るなど，奇抜な造形が親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003440"},{"id":"00009331","register_sub_id":"101","register_pk":"194124","name":"鮒鶴新館","kana":"ふなつるしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市下京区東木屋町通松原上る美濃屋町182-1他","lat":34.99922545,"lng":135.76875974,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄骨造4階地下1階建、鉄板葺、建築面積278㎡","structure_material":"鉄骨造4階地下1階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0404","desc":"本館の南に接続する鉄骨造四階建。緩勾配の入母屋造鉄板葺で破風を川側に見せる。川側三階までは縁と手摺で本館と意匠を揃え、三階庇上に唐破風を飾る。西側の三階建突出部はスクラッチタイル張で洋風の意匠も取入れる。近代の新構造に和風意匠をまとう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009331"},{"id":"00009330","register_sub_id":"101","register_pk":"194123","name":"鮒鶴本館","kana":"ふなつるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市下京区東木屋町通松原上る美濃屋町182-1他","lat":34.99931289,"lng":135.76886622,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造3階一部4階地下1階建、鉄板葺、建築面積273㎡、塔屋付","structure_material":"木造3階一部4階地下1階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0403","desc":"鴨川右岸に建つ木造三階建で、建築面積二七三平方メートル、木屋町通に玄関を構え、川側客室は縁の手摺で飾る。急勾配の屋根上にパラペットを廻らせ。四階屋根上に入母屋造の塔屋を設ける。地下にアールデコ意匠のダンスホールを持つ、近代の大規模和風料亭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009330"},{"id":"00009332","register_sub_id":"101","register_pk":"194125","name":"鮒鶴南門","kana":"ふなつるみなみもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市下京区東木屋町通松原上る美濃屋町182-1他","lat":34.99924151,"lng":135.76856046,"geo_status":"db","era":"昭和7年頃／平成13年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、瓦葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0405","desc":"木屋町通の新館玄関前に開く腕木門で、起り付の切妻造桟瓦葺とする。コンクリート基礎に立つ親柱は円柱で、門口は二・一メートル、上部に鶴に松の欄間彫刻を飾る。両脇の袖塀は門破風板の拝部まで立ち上げ、漆喰塗の腰を杉皮張とする。料亭入口の瀟洒な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009332"},{"id":"00005284","register_sub_id":"101","register_pk":"106272","name":"文椿ビルヂング（旧西村貿易店社屋）","kana":"ふみつばきびるぢんぐ（きゅうにしむらぼうえきてんしゃおく）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区三条通烏丸西入御倉町79","lat":35.00870507,"lng":135.75890862,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、銅板葺及びスレート葺、建築面積185㎡、地下室付","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"26 － 0208","desc":"木造２階建の事務所建築で，小屋組をキングポストトラスとし，銅板及びスレート葺のマンサード屋根を架ける。外壁はタイル張で，南面中央の入口部は８角断面を半割した片蓋柱で飾る。三条通と両替町通が交差する角地にあり，地域の近代的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005284"},{"id":"00003109","register_sub_id":"101","register_pk":"104099","name":"フランソア喫茶室","kana":"ふらんそあきっさしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市下京区西木屋町通四条下る船頭町184","lat":35.00334066,"lng":135.77020693,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"26 － 0141","desc":"繁華街木屋町にある喫茶店で，木造２階建の伝統的な長屋を洋風に改築したもの。今回の登録は昭和１６年改築の北半部分。設計は当時京大に留学していたイタリア人のベンチベニ氏で，京都の知識人のサロンとして長年親しまれてきた。内装や家具も良く残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003109"},{"id":"00010836","register_sub_id":"101","register_pk":"201671","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区六角通烏丸西入骨屋町155","lat":35.007508,"lng":135.759099,"geo_status":"db","era":"明治42／昭和10頃・同中期改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積311㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"26 ‐ 0492","desc":"六角通に南面する間口八間半の表屋造町家。表屋は上下階とも窓を並べ、西端の落棟部に虫籠窓を穿つ。住居部二階には、良材による洗練された意匠の造作を持つ大広間や茶室を配し、京町家として異色の接客空間を備える。鉾町に残る大型で上質な町家として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010836"},{"id":"00010837","register_sub_id":"101","register_pk":"201672","name":"松村家住宅土蔵","kana":"まつむらけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市中京区六角通烏丸西入骨屋町155","lat":35.007651,"lng":135.758992,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"26 ‐ 0493","desc":"主屋北西側、中庭の奥に南北棟で建つ。桁行七・八メートル梁間五・九メートル、土蔵造二階建、切妻造本瓦葺で、一階南妻の戸口に庇を付す。外壁漆喰塗で鉢巻を廻らし、腰を竪板張、二階南面には瓦庇の窓を穿つ。旧は反物を納めた土蔵で、庭空間を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010837"},{"id":"00004593","register_sub_id":"101","register_pk":"105583","name":"家邊徳時計店（家邊家住宅）店舗","kana":"やべとくとけいてん（やべけじゅうたく）てんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区三条通富小路東入中之町25","lat":35.00854896,"lng":135.7652399,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積107㎡","structure_material":"煉瓦造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0193","desc":"街路に北面して建つ煉瓦造２階建の店舗建築で，内部には金庫室や螺旋階段がある。１階は３連アーチを飾り，２階をセットバックさせる。エンタブレチュア，隅石に加え，豊かな装飾細部を随所に配す。三条通の近代的な町並景観の核として，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004593"},{"id":"00006540","register_sub_id":"101","register_pk":"107523","name":"山中油店主屋","kana":"やまなかあぶらてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区下立売通智恵光院西入下丸屋町508","lat":35.020157,"lng":135.745865,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積326㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0258","desc":"下立売通に南面する間口９間の平屋建町家。切妻造，桟瓦葺で表裏に庇が付き，北に落棟が続く。正面にはバッタリ床几と蔀，出格子，飾り窓を設け，つし２階に虫籠窓を開く。西半が通り土間，東半が２列の居室で，北奥に１０畳座敷を配す。京町家の典型として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006540"},{"id":"00000138","register_sub_id":"101","register_pk":"101128","name":"レストラン菊水","kana":"れすとらんきくすい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区川端通四条上る川端町187","lat":35.00397799,"lng":135.77319049,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造地上5階地下1階建塔屋付，建築面積203㎡","structure_material":"鉄筋コンクリート造地上5階地下1階建塔屋付","registered":"1997.05.07(平成9.05.07)","register_no":"26 － 0002","desc":"京都における西欧料理の草分け的な存在である菊水の店舗で，ＲＣ造，５階建ての正面に塔屋が付く。建物の様式は表現主義を基調とし，内外に様々な新様式を取り入れ見事にまとめている。内部は改装されているが，大正期の京都の新建築活動の規範的作品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000138"},{"id":"00004144","register_sub_id":"101","register_pk":"105134","name":"嶋臺巽蔵","kana":null,"category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区御池通烏丸東入仲保利町191","lat":35.01107891,"lng":135.76088898,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0170","desc":"御池通に面して建つ土蔵。３間四方の平面で，東と北の酒店側に扉口を開く。外観は腰縦板張，上部は漆喰塗とし，軒まで塗込め，屋根は本瓦葺である。内部は１階・２階とも柱を現し，いずれも一室とする。京都の近代初頭の景観を今日に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004144"},{"id":"00004141","register_sub_id":"101","register_pk":"105131","name":"嶋臺絲店","kana":null,"category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区御池通烏丸東入仲保利町191","lat":35.01108892,"lng":135.76068486,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積113㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0167","desc":"御池通りに南面して建つ。切妻造，桟瓦葺，平入で，西側を一段高く葺く。正面には庇をかけ，出格子を設ける。庇上の壁面は土壁とし，横長の虫籠窓を設けている。平面ほぼ中央南北に土間を通し，１階はその両脇を広い２室とする。近代初頭京町屋の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004141"},{"id":"00004142","register_sub_id":"101","register_pk":"105132","name":"嶋臺酒店","kana":null,"category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区御池通烏丸東入仲保利町191","lat":35.0111261,"lng":135.76093726,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積80㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0168","desc":"敷地の南東隅に建ち，東街路側を正面とする。平面は巽蔵を囲むＬ字型で，総土間とする。１階正面は連子格子を設け，南寄りに入り口を開く。庇上は土壁とし，虫籠窓を開く。御池通に面した妻面は上部白漆喰塗とし，巽蔵と連続する景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004142"},{"id":"00007663","register_sub_id":"101","register_pk":"108645","name":"石賀本店土蔵","kana":"いしがほんてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市法勝寺町22他","lat":35.42722138,"lng":133.33419086,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積104㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0147","desc":"南北に細長い敷地の南端に建ち、米子城旧外堀に面していた。桁行２０ｍ梁間６．０ｍの土蔵造２階建、東西棟の切妻造とし、北面に庇を通し、赤瓦を葺く。西から塗物蔵、米蔵、唐津蔵、倉庫の４室を設け、東寄りに石段の通用口を開く。旧外堀沿いの面影を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007663"},{"id":"00010500","register_sub_id":"101","register_pk":"199448","name":"植田家住宅主屋","kana":"うえだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県境港市末広町82","lat":35.546891,"lng":133.231548,"geo_status":"db","era":"明治中期／昭和58改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"31 － 0202","desc":"境港の市街地中心部で通りに東面して建つ、もと履物屋の町家建築。木造二階建、切妻造桟瓦葺で正面に下屋を設ける。平面は北側に土間を通し、床上部は居室を二列に配し、正面中央を玄関とする。赤色瓦が地方的特色を示し、通りに落ち着いた佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010500"},{"id":"00010501","register_sub_id":"101","register_pk":"199449","name":"植田家住宅離れ","kana":"うえだけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県境港市末広町82","lat":35.546823,"lng":133.231402,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"31 － 0203","desc":"主屋の西方に渡廊下を介して建つ。木造平屋建で下屋を廻らし、赤色瓦を葺く。内部は十畳と八畳の二室からなり、いずれも高く棹縁天井を張り、長押を廻らし、透彫欄間を飾る。軸部も、吟味した良質な材で建てられており、格調高い上質な空間を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010501"},{"id":"00010047","register_sub_id":"101","register_pk":"196194","name":"面谷家住宅旧砂糖蔵","kana":"おもたにけじゅうたくきゅうさとうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県境港市花町8","lat":35.54712588,"lng":133.24126217,"geo_status":"db","era":"明治後期／昭和19改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0190","desc":"店舗兼主屋の南に棟を連ねて建つ。土蔵造二階建、切妻造桟瓦葺で、西正面及び南面は腰を竪板張、上部を漆喰塗とし、西面には出窓と格子窓を穿つ。内部は二室に分かれ、南を土間、北を洋間とする。土間部は二階に部屋を設ける。敷地南西隅の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010047"},{"id":"00010045","register_sub_id":"101","register_pk":"196192","name":"面谷家住宅新座敷（旧精米所）","kana":"おもたにけじゅうたくしんざしき（きゅうせいまいじょ）","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県境港市花町8","lat":35.54733186,"lng":133.24144939,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積53㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0188","desc":"敷地の北、道具蔵の東に建つ土蔵で、元は精米所と伝えるが現在は座敷に改修されている。西から六畳、四畳半茶室、水屋を並べ、茶室北に小間を配す。茶室のトコはトコ柱に古材を用いる。南面は障子をたて縁を付す。大正期の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010045"},{"id":"00010044","register_sub_id":"101","register_pk":"196191","name":"面谷家住宅店舗兼主屋","kana":"おもたにけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県境港市花町8","lat":35.54723587,"lng":133.24131791,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺、建築面積180㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0187","desc":"島根県との県境、境水道南側の通りに西面して建つ、間口一〇間に及ぶ町家。切妻造桟瓦葺で前後に下屋を設け、つし部分は漆喰塗込とし虫籠窓を穿つ。平面は南端を土間、床上部は六間取とし、北東隅の座敷に座敷飾を備える。境港に残る数少ない醸造家の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010044"},{"id":"00010046","register_sub_id":"101","register_pk":"196193","name":"面谷家住宅道具蔵","kana":"おもたにけじゅうたくどうぐくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県境港市花町8","lat":35.54734649,"lng":133.24133862,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0189","desc":"主屋北に隣接し、道路に妻面を向けて建つ。土蔵造二階建、切妻造桟瓦葺で、店舗兼主屋側に出入口を設け、両開きの鉄扉を付す。西正面は腰高の簓子下見板張、上部を漆喰塗とし小窓を三箇所開け、他面は竪板張とする。主屋とともに屋敷の正面構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010046"},{"id":"00008161","register_sub_id":"101","register_pk":"132602","name":"木屋旅館","kana":"きやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県東伯郡三朝町大字三朝895他","lat":35.41023856,"lng":133.89429664,"geo_status":"db","era":"明治期／大正8年・昭和29年・昭和33年増築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階一部3階地下1階建、鉄板葺、建築面積516㎡","structure_material":"木造2階一部3階地下1階建","registered":"2010.04.28(平成22.04.28)","register_no":"31 － 0158","desc":"三朝温泉中心部の河畔に建つ旅館で、建築面積５１６㎡、木造２階建一部３階建、桟瓦葺及び鉄板葺で、地階に浴室を設ける。各客室は意匠を凝らし、外部は各階に庇を付け、窓に高欄を付ける。温泉街の発展とともに増築を重ね、複雑で特徴的な外観を造り上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008161"},{"id":"00012621","register_sub_id":"101","register_pk":"367915","name":"旧小倉家住宅主屋","kana":"きゅうおぐらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市河原町2884","lat":35.429565,"lng":133.812912,"geo_status":"geocoded","era":"昭和11年／昭和50年頃改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0255","desc":"市中心部西方の旧八橋往来沿いにある商家で、主屋は通りに北面して建つ。切妻造桟瓦葺の総二階建で、正面に下屋を付す。伝統形式を継承するが、たちの高いつくりで、正面二階の大きな掃出し窓、硝子窓桟の割付、手摺の意匠などに昭和前期の傾向が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012621"},{"id":"00012622","register_sub_id":"101","register_pk":"367916","name":"旧小倉家住宅土蔵","kana":"きゅうおぐらけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市河原町2884","lat":35.429565,"lng":133.812912,"geo_status":"geocoded","era":"大正5年頃／昭和50年頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0256","desc":"主屋の背面に近接して建つ。土蔵造二階建、南北棟の切妻造で、北面西寄りに戸口を開く。外壁は漆喰塗で小路に面する西面は階境に庇を通す。内部は上下階とも板敷で、和小屋を組む。旧八橋往来と川が交差する角地にあって商家町の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012622"},{"id":"00015372","register_sub_id":"101","register_pk":"532496","name":"旧山陰合同銀行根雨支店店舗","kana":"きゅうさんいんごうどうぎんこうねうしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県日野郡日野町根雨字屋敷466","lat":35.23773889,"lng":133.44182778,"geo_status":"db","era":"昭和2年／昭和54年頃改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"31 - 0298","desc":"出雲街道に東面する銀行店舗。木造寄棟造鉄板葺で、内部の正面側は吹抜で天井を折り上げ、中心飾を付す。正面は大オーダーの付柱を並べ、窓廻りをタイル貼、軒にコーニス廻らし、中央にペディメントを立上げレリーフを付す。昭和初期らしい外観の銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015372"},{"id":"00002089","register_sub_id":"101","register_pk":"103079","name":"旧塩屋出店主屋","kana":"きゅうしおやでみせしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭545","lat":35.26986531,"lng":134.22914504,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"31 － 0037","desc":"宿場町として栄えた智頭町の中心地近くに位置し，智頭街道に突き当たる街路に西面して建つ。木造２階建，切妻造，平入の町屋で，長大な正面のほぼ中央に玄関を置き，その北側をカミテ，南側をシモテとする。正面２階のたちが低く古式を感じさせる点に特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002089"},{"id":"00002092","register_sub_id":"101","register_pk":"103082","name":"旧塩屋出店外塀","kana":"きゅうしおやでみせそとべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭545","lat":35.26996616,"lng":134.22918762,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、瓦葺、延長9.9m","structure_material":"木造","registered":"2000.12.04(平成12.12.04)","register_no":"31 － 0040","desc":"主屋の北西端に発し，敷地北西端で東方に回り込み敷地北辺を限る塀。街道に沿った部分は腕木門風のつくりで，中央に門を開ける。敷地北辺の部分は瓦葺の屋根を載せた真壁造の土塀で，主屋北妻面との間に客用玄関口を形づくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002092"},{"id":"00000081","register_sub_id":"101","register_pk":"101071","name":"協同組合倉吉大店会（旧第三銀行倉吉支店）","kana":"きょうどうくみあいくらよしだいてんかい（きゅうだいさんぎんこうくらよししてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市魚町2540-1","lat":35.43163287,"lng":133.82646344,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積179㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"31 － 0001","desc":"倉吉の旧街道｢倉吉往来｣に面して建つ明治期の疑洋風建築の好例。当初第三銀行の支店として建造され，その後いくつかの金融機関を経て，現在は事務所として使用されている。旧往来に面した角地にあって，倉吉の中心街の明治期の様子を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000081"},{"id":"00008052","register_sub_id":"101","register_pk":"128883","name":"五臓圓ビル","kana":"ごぞうえんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市二階町2-207","lat":35.50151721,"lng":134.23064801,"geo_status":"db","era":"昭和6／昭和中期・昭和55・平成9改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積119㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2010.01.15(平成22.01.15)","register_no":"31-0156","desc":"角地に建つ鉄筋コンクリート造３階建、建築面積１１９㎡で、陸屋根とする。外壁はスクラッチタイル貼で、北隅を四分一円弧の曲面として上下に額縁を付し、パラペットも高めて隅部を強調する。鳥取市内で現存最古の本格的な鉄筋コンクリート造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008052"},{"id":"00016432","register_sub_id":"101","register_pk":"536499","name":"坂江家住宅店舗兼主屋","kana":"さかえけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県米子市灘町一丁目65","lat":35.43353611,"lng":133.32365,"geo_status":"db","era":"安政6年（1859）／明治24年・昭和中期改修","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"31 - 0300","desc":"加茂川河口の北側に位置し、かつて油屋を営んだ店舗兼主屋。間口二間、奥行九間、二階建切妻造平入桟瓦葺で二階の腰を海鼠壁とする。通り土間沿いにミセ、中の間、仏間、居間を一列に並べ、二階奥に八畳の座敷を配す。間口狭く、米子城下に残る貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016432"},{"id":"00016433","register_sub_id":"101","register_pk":"536500","name":"坂江家住宅土蔵","kana":"さかえけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市灘町一丁目65","lat":35.43369722,"lng":133.32363333,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積11㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"31 - 0301","desc":"主屋の北に中庭を挟んで位置する家財蔵。間口一間半、奥行二間半、土蔵造二階建、切妻造妻入桟瓦葺。外壁は白漆喰塗仕上で、腰は海鼠壁とする。内部は各階一室の板敷とし、柱、棟木、垂木の材は木太く、良材を用いた竪板張など、全体に良質なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016433"},{"id":"00006359","register_sub_id":"101","register_pk":"107342","name":"山陰民具店舗兼主屋","kana":"さんいんみんぐてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県倉吉市西岩倉町2196","lat":35.43244374,"lng":133.81764937,"geo_status":"db","era":"江戸後期／明治後期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階一部平屋建、瓦葺一部茅葺（鉄板仮葺）、建築面積119㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"31 － 0111","desc":"倉吉市街西部の西岩倉通の北側に位置する。間口５間、奥行６間半の平入町家である。表を瓦葺の２階建に改修しており、元の茅葺屋根を背面に残し、鉄板仮葺とする。内部は東半が幅の広い通り土間、西に１列３室の居室を配す。茅葺町家の歴史を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006359"},{"id":"00006278","register_sub_id":"101","register_pk":"107262","name":"高砂屋（城下町とっとり交流館）店舗棟","kana":"たかさごや（じょうかまちとっとりこうりゅうかん）てんぽとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市元大工町1","lat":35.4989019,"lng":134.23702769,"geo_status":"db","era":"明治後期／平成16曳家","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"31 － 0104","desc":"街道沿いに建つ商家建築。店舗棟と住居棟を東西に並べて配置する。店舗棟は、建築面積１３５㎡、木造２階建，桟瓦葺。間口一杯の差鴨居や太い柱を組んで、広い土間と帳場による店空間をつくる。特に土間の松梁は成があり長大で、往時の繁栄ぶりを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006278"},{"id":"00012012","register_sub_id":"101","register_pk":"210953","name":"東光園本館","kana":"とうこうえんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"鳥取県","address":"鳥取県米子市皆生温泉三丁目2155他","lat":35.457319,"lng":133.364932,"geo_status":"db","era":"昭和39年／平成3年改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄骨鉄筋コンクリート造7階建地下1階、建築面積761㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造7階建地下1階","registered":"2017.10.27(平成29.10.27)","register_no":"31-231","desc":"海岸に面して建つ鉄骨鉄筋コンクリート造地下一階地上七階建のホテル。六本の主柱が七階部分を支え、そこから五、六階の客室部を吊る構造で、各階とも異なる平面を実現している。階段部分などにも秀逸な構造デザインを見せる。メタボリズム建築の集大成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012012"},{"id":"00005490","register_sub_id":"101","register_pk":"106478","name":"豊田家住宅（久米郡倉吉驛）主屋","kana":"とよたけじゅうたく（くめごおりくらよしえき）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市西町2701","lat":35.43194737,"lng":133.8203568,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0095","desc":"東西に通る街路に北面して建つ。切妻造，桟瓦葺，平入，木造２階建で，正面は出桁造とする。構造は真壁造，正面外壁は鼠漆喰塗とし，２階開口部に手摺を設ける。倉吉の伝統的な町家形式を保持しており，打吹玉川保存地区に連なる町並み景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005490"},{"id":"00005491","register_sub_id":"101","register_pk":"106479","name":"豊田家住宅（久米郡倉吉驛）離れ","kana":"とよたけじゅうたく（くめごおりくらよしえき）はなれ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市西町2701","lat":35.43201122,"lng":133.82036389,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡、渡廊下付","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0096","desc":"南北に細長い敷地の南寄りにあり，前方の主屋と渡廊下で接続している。東西棟の切妻造，桟瓦葺，平入，２階建で，１階，２階とも床・棚を備えた６畳間とする。各所に上質の材を用い，床の間廻りは特に凝ったつくりで，昭和初期の熟達した和風の造形が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005491"},{"id":"00002298","register_sub_id":"101","register_pk":"103288","name":"米子専門大店","kana":"よなごせんもんだいてん","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県米子市道笑町1-111","lat":35.426682,"lng":133.335648,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積225㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.08.28(平成13.08.28)","register_no":"31 － 0041","desc":"市内中心部，道路の角地にたつ。鉄筋コンクリート造３階建で，縦長上げ下げ窓を街路側に配し，頂部に菱形の浮き彫りを施した付け柱をもつ石造風壁面からなる。米子銀行記章付の山型パラペットの下にデンティルを廻す。米子で最初の貸ビルで，原八十吉の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002298"},{"id":"00000360","register_sub_id":"101","register_pk":"101350","name":"旅館大橋大広間棟","kana":"りょかんおおはしおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41182651,"lng":133.89107231,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建，瓦葺，建築面積214㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"31 － 0020","desc":"温泉旅館を構成する建物の一つ。三徳川に沿って建ち並ぶ本館と離れの間に建つ。大規模な木造２階建の建物で，１階は厨房とし２階を大広間とする。左右一対の千鳥破風をつけた大屋根は，特徴的である。近年内部は改修されたが、外観は旧状を良く保っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000360"},{"id":"00000362","register_sub_id":"101","register_pk":"101352","name":"旅館大橋太鼓橋","kana":"りょかんおおはしたいこばし","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41197358,"lng":133.89027844,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造，瓦葺，建築面積23㎡","structure_material":"木造","registered":"1997.11.05(平成9.11.05)","register_no":"31 － 0022","desc":"本館と西離れを繋ぐ廊下で，公道から川岸に通じる通路をまたぐ太鼓橋に切妻造の上屋をかけた形式になる。本体部は円弧型の橋桁やや高欄をつけるなど本格的な造りとなる。道路側には橋の両端に灯明が付くなど凝った造作になり，温泉情緒を盛り上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000362"},{"id":"00000361","register_sub_id":"101","register_pk":"101351","name":"旅館大橋西離れ","kana":"りょかんおおはしにしはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41191355,"lng":133.8901944,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建一部2階，瓦葺，建築面積68㎡","structure_material":"木造平屋建一部2階","registered":"1997.11.05(平成9.11.05)","register_no":"31 － 0021","desc":"本館の右手に独立して建つ和風の建物で，本館とは太鼓橋で結ばれる。１階部分は露天風呂への脱衣室，２階は管理室となる。三徳川の下流側にあり，三角形の開口部や小庇，手摺等で外観を飾る。本館や離れ等とともに旅館建物の一つとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000361"},{"id":"00000310","register_sub_id":"101","register_pk":"101300","name":"旅館大橋離れ","kana":"りょかんおおはしはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41172244,"lng":133.89113853,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造3階建，瓦葺，建築面積312㎡","structure_material":"木造3階建","registered":"1997.09.03(平成9.09.03)","register_no":"31 － 0019","desc":"本館の左手に接続する和風の建物。入母屋造３階建の建屋と寄棟造２階建の建屋からなるが，一体として使用される。客室はやや広めで，各客室は本館同様に意匠を凝らした上品な造りになる。三徳川沿いに展開する雄姿は，三朝温泉の象徴的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000310"},{"id":"00000309","register_sub_id":"101","register_pk":"101299","name":"旅館大橋本館","kana":"りょかんおおはしほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41189274,"lng":133.89057559,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造3階建，瓦葺，建築面積625㎡","structure_material":"木造3階建","registered":"1997.09.03(平成9.09.03)","register_no":"31 － 0018","desc":"大橋旅館は三朝温泉郷の老舗温泉旅館の一つで，三徳川に沿って本館や離れ等が軒を連ねている。本館は，木造３階建になり，１階正面左手に玄関を設け，各階に意匠を凝らした上品な客室を配する。優雅な和風の外観は，三朝温泉の歴史と伝統を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000309"},{"id":"00010991","register_sub_id":"101","register_pk":"208961","name":"カラコロ工房（旧日本銀行松江支店）","kana":"からころこうぼう（きゅうにほんぎんこうまつえしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市殿町43","lat":35.470367,"lng":133.053441,"geo_status":"db","era":"昭和13／昭和56・平成12改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積633㎡、塔屋、煙突及び塀付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2016.02.25(平成28.02.25)","register_no":"32-0178","desc":"長野宇平治の設計で昭和一三年に完成した。鉄筋コンクリート造三階建、地下一階で、塔屋と煙突を有する。外観はギリシャ神殿風の意匠でまとめ、営業室と客溜は吹き抜けの大空間で、地下は金庫室である。当初形式をよく保持し、地域の核として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010991"},{"id":"00008356","register_sub_id":"101","register_pk":"133998","name":"河田商店奥の蔵","kana":"かわだしょうてんおくのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.46810931,"lng":131.77375384,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0148","desc":"庭の蔵の西に東西棟で建つ。桁行５．９ｍ梁間５．９ｍ、切妻造桟瓦葺の２階建土蔵で、南面を葺き降ろして蔵前とする。１階は二室、２階は一室で、２階には蔵前から入る。腰板張で、蔵前も含めて大壁造で塗り込める。装飾のない、質実な蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008356"},{"id":"00008353","register_sub_id":"101","register_pk":"133995","name":"河田商店店舗兼主屋","kana":"かわだしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.467937,"lng":131.77393671,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積217㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0145","desc":"東の通りと、南の小路に画される敷地の東端に位置する。間口９．９ｍの木造つし２階建、切妻造桟瓦葺の平入町家で、北面に落棟で座敷や仏間を付設する。壁は大壁で、正面は大きく開口を穿ち、小路側は庇付の窓を三ヶ所穿つ。骨太で剛直な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008353"},{"id":"00008355","register_sub_id":"101","register_pk":"133997","name":"河田商店庭の蔵","kana":"かわだしょうてんにわのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.46806711,"lng":131.77382418,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0147","desc":"主屋の西方、庭を挟んだ位置に南北棟で建つ。桁行８．８ｍ梁間４．７ｍの２階建土蔵。切妻造で、桟瓦を葺く。壁は腰竪板張の漆喰仕上げで、南面に庇付の窓を上下に設ける。庭側の東面は腰を海鼠壁とし、出入口を開け、桟瓦葺庇を付け、庭園景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008355"},{"id":"00008354","register_sub_id":"101","register_pk":"133996","name":"河田商店離れ","kana":"かわだしょうてんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.46804601,"lng":131.77390857,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積22㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0146","desc":"主屋の西北に東西棟で建つ。桁行７．２ｍ梁間３．３ｍの木造２階建で南面に縁を付設する。切妻造桟瓦葺で、東妻面は下屋を付け、妻を大壁で塗り込め、土蔵風に見せる。庭に南面し、１階に二室、２階に一室配し、２階はトコや棚、平書院を設ける書院座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008354"},{"id":"00008357","register_sub_id":"101","register_pk":"133999","name":"河田商店本蔵","kana":"かわだしょうてんほんぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.468038,"lng":131.77367899,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0149","desc":"敷地の南辺、主屋角屋の西に続く。桁行１４ｍ梁間５．９ｍの土蔵造２階建。切妻造桟瓦葺で、東寄りの棟を一段下げる。内部は東寄りと西側に大きく分かれる。石積基礎に建ち、腰海鼠壁とする漆喰仕上げで、要所に開口を設ける。主屋と一連で街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008357"},{"id":"00014085","register_sub_id":"101","register_pk":"508345","name":"旧濱中屋船宿（福間館別館）","kana":"きゅうはまなかやふなやど（ふくまかんべっかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県松江市美保関町美保関296","lat":35.56142222,"lng":133.31142222,"geo_status":"db","era":"明治44年頃","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"32 - 0214","desc":"美保関東端の通りに南面する船宿。二階建切妻造桟瓦葺で軒は出桁造。内部は東に通り土間、西に一列二室を配し、二階は前後に三室配置。出桁や木鼻付持送など美保関の町家の特徴を示す。二階の建ちの高い整った座敷から湾を眺望でき、船宿の特徴をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014085"},{"id":"00008339","register_sub_id":"101","register_pk":"133981","name":"旧布施時計店店舗兼主屋","kana":"きゅうふせとけいてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ192-1","lat":34.46858669,"lng":131.77468575,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0131","desc":"通りに西面する木造２階建、桟瓦葺。正面１階を店舗、２階及び背面を住居として建設。正面側はパラペットを立ち上げ、モルタル仕上げとし、２階角に大きく窓を切り欠き、要所に円窓を開ける。１階入口にはショウウインドウが残る。伝統的な町並に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008339"},{"id":"00002980","register_sub_id":"101","register_pk":"103970","name":"旧米江旅館本館北棟","kana":"きゅうよねえりょかんほんかんきたとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市伊勢宮町535","lat":35.465717,"lng":133.059967,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"32 － 0011","desc":"松江城下の市街地にある老舗の旅館建築。敷地北側の街路に面して建つ北棟は，切妻造・平入の２階建で，入母屋造の玄関を設ける。２階を客室６室とするが，各室ごとに良質の銘木・珍木を用い趣向を凝らした座敷飾を整え，当時の和風建築のあり様を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002980"},{"id":"00002981","register_sub_id":"101","register_pk":"103971","name":"旧米江旅館本館南棟","kana":"きゅうよねえりょかんほんかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市伊勢宮町535","lat":35.46558,"lng":133.060028,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造一部鉄筋コンクリート造2階建、瓦葺、建築面積124㎡","structure_material":"木造一部鉄筋コンクリート造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"32 － 0012","desc":"松江城下の市街地にある老舗の旅館建築。敷地南側の街路に面して建つ南棟は，切妻造・平入の２階建で，１階を食堂と茶室，２階を客室３室とする。２階１５畳の広間は折上格天井で，繊細な付書院を備える。よく吟味した材料を用い，瀟洒な造形にまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002981"},{"id":"00010688","register_sub_id":"101","register_pk":"201262","name":"ごうぎんカラコロ美術館（旧山陰合同銀行北支店）","kana":"ごうぎんからころびじゅつかん（きゅうさんいんごうどうぎんこうきたしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市殿町412","lat":35.470379,"lng":133.054199,"geo_status":"db","era":"大正15年／平成24年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積389㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2015.08.04(平成27.08.04)","register_no":"32－0173","desc":"鉄筋コンクリート造二階建で、西面して建つ。営業室と客溜は二層吹抜けの大空間とし、北側に重役室などを配し、北東隅に金庫室を設ける。松江城南東の金融街に位置し、大オーダーの六本付柱、メダリオンの装飾、隅丸の石造風外壁が、地域景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010688"},{"id":"00008362","register_sub_id":"101","register_pk":"134004","name":"ささや呉服店唐津蔵","kana":"ささやごふくてんからつぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ213","lat":34.46896566,"lng":131.77421863,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0154","desc":"敷地の西南に位置する。桁行６．７ｍ梁間３．７ｍの土蔵造２階建、切妻造妻入で、桟瓦を葺く。割石基礎とし、外壁は漆喰で仕上げる。東面に出入口を設け、瓦葺庇を付け、掛子塗の両開戸を吊る。上部に窓を穿ち、銅製の片開戸を設ける。屋敷景観を整える一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008362"},{"id":"00008361","register_sub_id":"101","register_pk":"134003","name":"ささや呉服店旧呉服蔵","kana":"ささやごふくてんきゅうごふくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ213","lat":34.46888314,"lng":131.77454872,"geo_status":"db","era":"江戸末期／昭和40年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0153","desc":"主屋の南、玄関を挟んで東西棟で建つ。桁行５．９ｍ梁間３．９ｍの土蔵造２階建。切妻造で、桟瓦で葺く。外壁は漆喰仕上げで、通り側には腰を海鼠壁とし、各階に瓦庇付の窓を開け、銅製の開戸を吊り、上部に家紋を飾る。主屋と一体で、街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008361"},{"id":"00008360","register_sub_id":"101","register_pk":"134002","name":"ささや呉服店座敷蔵","kana":"ささやごふくてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ213","lat":34.46891964,"lng":131.7743932,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0152","desc":"主屋の西南に位置する。桁行５．８ｍ梁間３．２ｍの土蔵造２階建、東西棟の切妻造で、桟瓦を葺く。外壁は漆喰仕上げで、２階東面に鉄格子付の窓を穿つ。１階を六畳の座敷とし、東面から南面にかけて、二段に縁を設け、磨丸太の垂木を配るなど数寄屋風意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008360"},{"id":"00008359","register_sub_id":"101","register_pk":"134001","name":"ささや呉服店店舗兼主屋","kana":"ささやごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ213","lat":34.4689601,"lng":131.77460416,"geo_status":"db","era":"江戸末期／昭和44年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積207㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0151","desc":"通りに東面する町家。間口１４ｍ木造２階建、切妻造桟瓦葺とし、銅瓦棒葺の下屋庇を付け、背面は葺き降ろす。北側の小路に大きく妻壁を見せ、庇付の窓を二ヶ所開ける。大壁造とし、両端にウダツを設け、庇には幕板を付ける。商家の表構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008359"},{"id":"00008358","register_sub_id":"101","register_pk":"134000","name":"俵種苗店店舗兼主屋","kana":"たわらしゅびょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ212","lat":34.46879884,"lng":131.77447791,"geo_status":"db","era":"明治中期／大正前期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0150","desc":"通りに東面する町家。間口１０ｍの木造つし２階建、切妻造桟瓦葺とし、東面に鉄板葺の庇を付ける。正面を広い土間の店舗とし、その奥は北寄りに通り土間、南に四間取の床上を設ける。正面には揚戸を残すなど、津和野の伝統的な町家の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008358"},{"id":"00010889","register_sub_id":"101","register_pk":"201724","name":"日の出館玄関棟","kana":"ひのでかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県出雲市大社町杵築南776","lat":35.39519,"lng":132.6869,"geo_status":"db","era":"大正5／平成3改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"32 ‐ 0176","desc":"出雲大社の南に延びる参道東側に位置し、大正三年の神門通り開通後の建築である。西面して建つ木造二階建で、正面に入母屋造の玄関を備える。一階は玄関とロビー、二階は客室二室で、八畳に簡明な座敷飾を備える。近代における大社詣の歴史を物語る和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010889"},{"id":"00010890","register_sub_id":"101","register_pk":"201725","name":"日の出館明治棟","kana":"ひのでかんめいじとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県出雲市大社町杵築南776","lat":35.395241,"lng":132.686847,"geo_status":"db","era":"明治前期／平成3改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"32 ‐ 0177","desc":"玄関棟北に接続し、取合状況からも玄関棟より古いと判る。南面して建つ木造二階建、切妻造桟瓦葺で、客室は一階が二室、二階が控室付の四室で、各部屋とも整った座敷飾を備え、瀟洒なつくりになる。大社詣にかかる数少ない木造旅館建築として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010890"},{"id":"00016721","register_sub_id":"101","register_pk":"579205","name":"福寿苑店舗","kana":"ふくじゅえんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県松江市天神町142他","lat":35.464841,"lng":133.055913,"geo_status":"db","era":"昭和26年／平成前期改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積113㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2026.07.09(令和8.07.09)","register_no":"32 - 0223","desc":"天神町の四ツ角に位置する旧呉服問屋の店舗。鉄筋コンクリート造2階一部３階建。外壁モルタル塗仕上。矩形の北西隅にアールを付した平面で、縦長窓や丸窓を配したアールデコ風の端正な外観。交差点の顔をつくり、昭和24年大火後の耐火建築としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016721"},{"id":"00008337","register_sub_id":"101","register_pk":"133979","name":"分銅屋ござ蔵及びびんつけ蔵","kana":"ぶんどうやござぐらおよびびんつけぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ190他","lat":34.46839977,"lng":131.77491263,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積52㎡、便所付","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0129","desc":"主屋の後方、土蔵の東北に位置する。桁行１３ｍ梁間４．０ｍの切妻造桟瓦葺で、東半部の棟を下げる。壁は腰モルタルで、上部は西寄りが漆喰仕上げ、東側が中塗仕上げである。西面北寄りに桁行３．１ｍ梁間１．１ｍの木造便所を付設する。作業場の名残を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008337"},{"id":"00008335","register_sub_id":"101","register_pk":"133977","name":"分銅屋店舗兼主屋","kana":"ぶんどうやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ190他","lat":34.46849208,"lng":131.77458295,"geo_status":"db","era":"安政(1854-60)頃／昭和前期改修","year":1856,"year_source":"estimated","year_min":1854,"year_max":1859,"year_label":"安政","structure":"木造平屋建、鉄板葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0127","desc":"通りに西面する間口１１ｍの町家。切妻造鉄板葺で、当初はつし２階建。正面に下屋庇を付け、背面は葺き降ろし、台所や便所を付設する。漆喰仕上げで、２階に広く格子窓を穿ち、１階には格子戸をたて、幕板のガラスに家紋をあしらう。津和野における町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008335"},{"id":"00008336","register_sub_id":"101","register_pk":"133978","name":"分銅屋土蔵","kana":"ぶんどうやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ190他","lat":34.46840505,"lng":131.77475438,"geo_status":"db","era":"安政(1854-60)頃","year":1856,"year_source":"estimated","year_min":1854,"year_max":1859,"year_label":"安政","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0128","desc":"主屋の東後方に位置する。桁行８．５ｍ梁間４．５ｍの土蔵造２階建。東西棟の切妻造とし、桟瓦で葺き、西面に出入口を開き、鉄板葺庇を付ける。切石基礎上に、腰板張で、上部漆喰仕上げとし、妻上部に家紋をつくり出す。屋敷構えを構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008336"},{"id":"00008338","register_sub_id":"101","register_pk":"133980","name":"分銅屋はぜ蔵","kana":"ぶんどうやはぜぐらはぜ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ190他","lat":34.4682468,"lng":131.7752133,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積83㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0130","desc":"東西に長い敷地の東端に位置する。桁行１３ｍ梁間５．９ｍの土蔵造平屋建。東西棟の切妻造桟瓦葺で、南面に間口４．２ｍ奥行１．３ｍの庇を付ける。石積基礎上に建ち、漆喰仕上げで腰竪板張とし、窓に銅製の戸をたてる。赤瓦と白漆喰に戸の緑青が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008338"},{"id":"00012449","register_sub_id":"101","register_pk":"531773","name":"保性館幽泉亭","kana":"ほせいかんゆうせんてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県松江市玉湯町玉造1191-1他","lat":35.41553056,"lng":133.00906111,"geo_status":"db","era":"昭和6年／平成元年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"32-190","desc":"玉造温泉にある皇族専用の宿泊棟。川島徳次郎の作で、入母屋造桟瓦葺の周囲を錣風の屋根とした重厚な構成を鉄材を用いた薄く深い軒で軽快にみせる。内部は多彩な意匠を駆使して創意あふれた数寄屋風にまとめる。当地域の大工の高度な技量が発揮された秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012449"},{"id":"00010346","register_sub_id":"101","register_pk":"199119","name":"山常楼主屋","kana":"やまつねろうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県安来市安来町字内浜1704","lat":35.430006,"lng":133.254796,"geo_status":"db","era":"昭和9年頃／昭和51年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積596㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"32-0168","desc":"安来港の山陰道沿いに位置する。木造二階建の座敷棟を二棟南北に並列させ、北棟から廊下で奥座敷棟に接続する。特に北棟二階に三室続く座敷は併せて七七畳の大空間となる。広間の座敷飾や高欄腰組等の造作も贅が尽くされ、安来鋼で栄えた港町を彩る料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010346"},{"id":"00010347","register_sub_id":"101","register_pk":"199120","name":"山常楼土蔵","kana":"やまつねろうどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県安来市安来町字内浜1704","lat":35.429899,"lng":133.255063,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"32-0169","desc":"奥座敷の南方に東西棟で建つ二階建の土蔵で、東と南に開口部を設ける。内部は東西二室に分け、それぞれに階段を持つ。東面二階の窓廻りは、庇を腕木から軒先まで丁寧に塗込め、掛子塗の扉を吊り、高い左官技術を示す。主屋とともに街道からの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010347"},{"id":"00004615","register_sub_id":"101","register_pk":"105605","name":"山本家住宅主屋","kana":"やまもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里71","lat":35.35093848,"lng":133.27469924,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積199㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0034","desc":"切妻造，平入で，街道に東面して建つ。真壁造，平屋建，屋根桟瓦葺で，外観は全体がつし２階建になり，１階正面には蔀戸や出格子を設ける。１階は南側を通り土間，北側を床上とし，庭を望む北妻の客間は開放的な構えになる。地域の指標となる明治前期の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004615"},{"id":"00004298","register_sub_id":"101","register_pk":"105288","name":"旅館美保館旧本館","kana":"りょかんみほかんきゅうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市美保関町美保関570","lat":35.56275654,"lng":133.30790442,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積482㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"32 － 0028","desc":"美保神社への参道北側にあり，棟札から大工河合藤助が判明。南面して建つ木造２階建の和風旅館で，１階は事務室等とし，客室は２階に配する。切妻造，桟瓦葺，平入で，南面には出桁造で中央切妻破風付の庇を設ける。数寄屋風の簡明な意匠で纏められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004298"},{"id":"00004297","register_sub_id":"101","register_pk":"105287","name":"旅館美保館本館","kana":"りょかんみほかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県松江市美保関町美保関573","lat":35.56260008,"lng":133.30809978,"geo_status":"db","era":"明治41／大正期増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積604㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"32 － 0027","desc":"美保神社への参道沿いにある。木造２階建の和風旅館で，切妻造，桟瓦葺の２棟が細長い敷地の南北に建ち，その間をホール（中庭）で接続し，北面には中央に軒唐破風付の庇を設ける。全体は繊細な数寄屋風で，窓，欄間，手摺など各部に趣向が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004297"},{"id":"00001644","register_sub_id":"101","register_pk":"102634","name":"あけぼの旅館","kana":"あけぼのりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県津山市戸川町31-1、32-1","lat":35.05913655,"lng":133.99971555,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積238㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0046","desc":"津山市内で現存する旅館の中で最も古い旅館建築とされる。表側は道路拡幅のため１階に改造されているが，奥の２階建部分は水廻りを除いて書院造風の内部造作をよく残す。旧城下町のたたずまいを残す地区の一画にあり，景観的に重要な位置を占めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001644"},{"id":"00001531","register_sub_id":"101","register_pk":"102521","name":"江見写真館","kana":"えみしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市山下28","lat":35.05957007,"lng":134.00233804,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積187㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"33 － 0032","desc":"津山における草分け的存在の写真館。正面を西に向け，玄関の右手に半円形の応接室を張り出し，玄関上部には成の高い縦長の２連アーチ窓を開ける。北面には屋根面に達する高窓を設けるなど写真館建築の特徴をよく伝える。設計は地元の原田（熊二郎）工務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001531"},{"id":"00005195","register_sub_id":"101","register_pk":"106185","name":"おかやま旧日銀ホール（旧日本銀行岡山支店本館）","kana":"おかやまきゅうにちぎんほーる（きゅうにっぽんぎんこうおかやましてんほんかん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区内山下1-6-20","lat":34.6614,"lng":133.930756,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造及び石造2階建、建築面積520㎡","structure_material":"煉瓦造及び石造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"33 － 0101","desc":"県庁に近い市中心部に位置する。外装に花崗岩を用いた煉瓦造及び石造建造物で，小屋組は鉄骨トラスとする。正面中央にコリント式オーダーと三角ペディメントをあしらうなど古典主義様式の格調高いデザインが特徴的。設計は長野宇平治，施工は藤木工務店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005195"},{"id":"00012642","register_sub_id":"101","register_pk":"367936","name":"奥津荘本館","kana":"おくつそうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町奥津字湯ノ前49","lat":35.216263,"lng":133.942337,"geo_status":"geocoded","era":"昭和10年頃／昭和30年頃・平成16年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積328㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0307","desc":"奥津温泉中心部にある旅館で、街路に東面して建つ。木造総二階建、入母屋造桟瓦葺で棟を矩折れに配し、正面北端の唐破風の玄関上に大屋根の妻面を重ねる。一階全面に並んだ格子や出桁造の深い軒など立体感のある外観で、温泉街の歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012642"}];
